def _sig(path: Path, size: int = 10, mtime: int = 1) -> dict:
    return {"pathKey": f"{path}|{size}|{mtime}", "size": size, "mtimeNs": mtime}


def _write_exif_photo(path: Path) -> None:
    from PIL import ExifTags, Image, TiffImagePlugin

    image = Image.new("RGB", (8, 6), "blue")
    exif = Image.Exif()
    exif[306] = "2025:04:03 02:01:00"
    exif[271] = "TestMake"
    exif[272] = "TestModel"
    rational = TiffImagePlugin.IFDRational
    exif[274] = 6
    exif[33434] = rational(1, 125)
    exif[33437] = rational(28, 10)
    exif[34855] = 200
    exif[37386] = rational(26, 1)
    exif[41989] = 52
    exif[42036] = "Test Lens 26mm"
    exif[ExifTags.IFD.GPSInfo] = {
        1: "N",
        2: (rational(36, 1), rational(58, 1), rational(2664, 100)),
        3: "W",
        4: (rational(122, 1), rational(1, 1), rational(508, 100)),
    }
    image.save(path, exif=exif, quality=95)


def _write_pattern_photo(path: Path, variant: str) -> None:
    from PIL import Image

    image = Image.new("RGB", (32, 32), "black")
    pixels = image.load()
    for y in range(32):
        for x in range(32):
            if variant == "distant":
                value = 40 if (x // 2) % 2 else 220
            else:
                value = 220 if (x // 2) % 2 else 40
                value = max(0, min(255, value + (y % 5) * 3))
                if variant == "near" and 12 <= x < 15 and 12 <= y < 15:
                    value = 255 - value
            pixels[x, y] = (value, value, value)
    image.save(path, quality=95)


def _fake_rawpy_module(width: int = 48, height: int = 36) -> Any:
    import importlib.machinery
    import types

    import numpy as np

    module = types.ModuleType("rawpy")
    module.__spec__ = importlib.machinery.ModuleSpec("rawpy", loader=None)

    class FakeSizes:
        pass

    FakeSizes.raw_width = width
    FakeSizes.raw_height = height
    FakeSizes.width = width
    FakeSizes.height = height

    class FakeRaw:
        sizes = FakeSizes()

        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def postprocess(self, *_args, **_kwargs):
            data = np.zeros((height, width, 3), dtype=np.uint8)
            for y in range(height):
                for x in range(width):
                    data[y, x] = (
                        32 + (x * 4) % 180,
                        48 + (y * 5) % 170,
                        96 + ((x + y) * 3) % 140,
                    )
            return data

    module.imread = lambda _path: FakeRaw()
    return module


def _write_tiny_video(path: Path) -> bool:
    try:
        import cv2
        import numpy as np
    except Exception:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    for codec in ("mp4v", "avc1", "MJPG", "XVID"):
        writer = None
        try:
            fourcc = cv2.VideoWriter_fourcc(*codec)
            writer = cv2.VideoWriter(str(path), fourcc, 6.0, (64, 64))
            if not writer.isOpened():
                writer.release()
                continue
            for index in range(8):
                frame = np.zeros((64, 64, 3), dtype=np.uint8)
                frame[:, :, 0] = 30 + index * 16
                frame[:, :, 1] = 120
                frame[:, :, 2] = 210 - index * 12
                cv2.putText(frame, str(index), (18, 42), cv2.FONT_HERSHEY_SIMPLEX, 0.8, (255, 255, 255), 2)
                writer.write(frame)
            writer.release()
            if path.exists() and path.stat().st_size > 0:
                return True
        except Exception:
            if writer is not None:
                try:
                    writer.release()
                except Exception:
                    pass
    return False


def _real_ffmpeg_path() -> str:
    for candidate in (
        os.environ.get("VINTRACE_FFMPEG_PATH", ""),
        os.environ.get("CROSSAGE_FFMPEG_PATH", ""),
        shutil.which("ffmpeg") or "",
    ):
        if candidate and Path(candidate).expanduser().is_file():
            return str(Path(candidate).expanduser())
    try:
        import imageio_ffmpeg

        candidate = imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:
        candidate = ""
    if candidate and Path(candidate).expanduser().is_file():
        return str(Path(candidate).expanduser())
    return ""


def _write_real_ffmpeg_video_fixture(ffmpeg: str, path: Path) -> bool:
    path.parent.mkdir(parents=True, exist_ok=True)
    completed = subprocess.run(
        [
            ffmpeg,
            "-hide_banner",
            "-loglevel",
            "error",
            "-f",
            "lavfi",
            "-i",
            "testsrc=size=64x64:rate=6:duration=1",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=330:sample_rate=48000:duration=1",
            "-shortest",
            "-c:v",
            "libx264",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-b:a",
            "96k",
            "-y",
            str(path),
        ],
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    return completed.returncode == 0 and path.exists() and path.stat().st_size > 100


def _ffmpeg_decode_summary(ffmpeg: str, path: Path) -> str:
    completed = subprocess.run(
        [
            ffmpeg,
            "-hide_banner",
            "-i",
            str(path),
            "-f",
            "null",
            "-",
        ],
        capture_output=True,
        text=True,
        timeout=120,
        check=False,
    )
    assert completed.returncode == 0, (path, completed.stderr, completed.stdout)
    return f"{completed.stderr}\n{completed.stdout}".lower()


