def test_photo_library_backup_check_reports_local_readiness() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        keeper = base / "keeper.jpg"
        _write_exif_photo(keeper)
        keeper_path = str(keeper.resolve())
        sidecar = base / "keeper.xmp"
        sidecar.write_text("xmp sidecar", encoding="utf-8")

        referenced = api.import_photos(
            {
                "sourcePaths": [str(keeper)],
                "storageMode": "referenced",
                "sourceLabel": "Backup referenced",
            }
        )
        assert referenced["importedPaths"] == [keeper_path], referenced

        missing = Path(str((base / "missing.jpg").resolve()))
        api.project.db.create_scan_run("run-missing", "Missing card", "manual", str(base))
        api.project.db.record_scan_file(
            "run-missing",
            missing,
            _sig(missing, size=10, mtime=2),
            "completed",
            phase="processed",
        )

        managed_source = base / "managed.jpg"
        _write_exif_photo(managed_source)
        managed_root = base / "managed-library"
        managed = api.import_photos(
            {
                "sourcePaths": [str(managed_source)],
                "storageMode": "managed",
                "managedRoot": str(managed_root),
                "sourceLabel": "Backup managed",
            }
        )
        managed_path = managed["importedPaths"][0]
        api.rebuild_photo_previews({"sourcePaths": [keeper_path, managed_path], "force": True})

        keeper_asset = api.project.db.photo_asset_by_path(keeper_path)
        assert keeper_asset, keeper_asset
        api.update_photo_asset_metadata(
            {
                "assetId": keeper_asset["assetId"],
                "title": "Keeper",
                "favorite": True,
                "keywords": ["safe"],
            }
        )
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, 'accepted', 0.99, 0.95, 'manual assignment', '2026-06-20T00:00:00Z')
                """,
                (keeper_asset["assetId"], "manual-keeper", "Alice"),
            )
        album = api.save_photo_album({"name": "Backup picks", "albumKind": "manual"})
        api.add_photo_album_items({"albumId": album["albumId"], "sourcePaths": [keeper_path]})

        result = api.photo_library_backup_check({})
        assert result["ok"] is False, result
        assert result["status"] == "attention", result
        counts = result["counts"]
        assert counts["assets"] == 3, counts
        assert counts["referencedAssets"] == 2, counts
        assert counts["managedAssets"] == 1, counts
        assert counts["missingOriginals"] == 1, counts
        assert counts["missingReferencedOriginals"] == 1, counts
        assert counts["missingManagedOriginals"] == 0, counts
        assert counts["previewEligibleAssets"] == 2, counts
        assert counts["cachedPreviews"] == 2, counts
        assert counts["missingCachedPreviews"] == 0, counts
        assert counts["existingSidecars"] == 1, counts
        assert counts["metadataRows"] >= 1, counts
        assert counts["keywordAssignments"] == 1, counts
        assert counts["peopleLinks"] == 1, counts
        assert counts["albums"] >= 1, counts
        assert counts["manualAlbums"] >= 1, counts
        assert counts["albumItems"] == 1, counts
        assert counts["orphanAlbumItems"] == 0, counts
        assert counts["catalogIntegrityIssues"] == 0, counts
        assert result["samples"]["missingOriginals"][0]["sourcePath"] == str(missing), result
        assert result["samples"]["existingSidecars"][0]["sidecars"] == [str(sidecar.resolve())], result
        assert any(check["id"] == "originals-present" and not check["ok"] for check in result["checks"]), result
        assert any("referenced original" in item for item in result["recommendations"]), result
    print("ok Photos backup readiness reports originals, previews, metadata, sidecars, and albums")


