def test_photo_library_backup_check_chunks_scoped_asset_queries() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        scoped_root = base / "chunked-library"
        scoped_root.mkdir()
        photos = []
        for index in range(5):
            photo = scoped_root / f"chunked-{index}.jpg"
            _write_exif_photo(photo)
            photos.append(str(photo))
        imported = api.import_photos({
            "sourcePaths": photos,
            "storageMode": "referenced",
            "sourceLabel": "Chunked backup root",
        })
        asset_ids: list[str] = []
        for index, source_path in enumerate(imported["importedPaths"]):
            asset = api.project.db.photo_asset_by_path(source_path)
            assert asset, source_path
            asset_id = str(asset["assetId"])
            asset_ids.append(asset_id)
            api.update_photo_asset_metadata({
                "assetId": asset_id,
                "title": f"Chunked {index}",
                "keywords": [f"chunked-{index}"],
            })

        album = api.save_photo_album({"name": "Chunked manual", "albumKind": "manual"})
        api.add_photo_album_items({"albumId": album["albumId"], "sourcePaths": imported["importedPaths"]})
        with api.project.db.connect() as conn:
            conn.executemany(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, 'Chunked Person', 'accepted', 0.99, 0.95, 'manual assignment', '2026-06-20T00:00:00Z')
                """,
                [(asset_id, f"chunked-person-{index}") for index, asset_id in enumerate(asset_ids)],
            )
        raw_conn = sqlite3.connect(str(api.project.db.path))
        try:
            raw_conn.execute("PRAGMA foreign_keys = OFF")
            raw_conn.executemany(
                "INSERT INTO photo_album_items(album_id, asset_id, position, added_at) VALUES(?, ?, ?, ?)",
                [
                    ("missing-chunked-album", asset_ids[1], 100, "2026-06-20T00:00:00Z"),
                    ("missing-chunked-album", asset_ids[3], 101, "2026-06-20T00:00:00Z"),
                ],
            )
            raw_conn.commit()
        finally:
            raw_conn.close()

        original_chunk_size = api_server_module.SQLITE_IN_CLAUSE_CHUNK_SIZE
        api_server_module.SQLITE_IN_CLAUSE_CHUNK_SIZE = 2
        try:
            result = api.photo_library_backup_check({"sampleLimit": 10, "libraryRoot": str(scoped_root.resolve())})
        finally:
            api_server_module.SQLITE_IN_CLAUSE_CHUNK_SIZE = original_chunk_size

        counts = result["counts"]
        assert counts["assets"] == 5, counts
        assert counts["metadataRows"] == 5, counts
        assert counts["keywordAssignments"] == 5, counts
        assert counts["peopleLinks"] == 5, counts
        assert counts["albumItems"] == 7, counts
        assert counts["orphanAlbumItems"] == 2, counts
        assert {row["asset_id"] for row in result["samples"]["orphanAlbumItems"]} == {asset_ids[1], asset_ids[3]}, result
    print("ok Photos backup readiness chunks scoped asset-id queries")


def test_photo_library_backup_check_reports_managed_root_profile_drift() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        managed_root = base / "managed-root"
        api.save_photo_library_settings({
            "defaultManagedRoot": str(managed_root),
            "defaultStorageMode": "managed",
            "profileName": "Managed root",
        })
        source = base / "managed-profile-drift.jpg"
        _write_exif_photo(source)
        imported = api.import_photos({
            "sourcePaths": [str(source)],
            "storageMode": "managed",
            "sourceLabel": "Managed profile drift",
        })
        assert imported["importedCount"] == 1, imported
        managed_path = imported["importedPaths"][0]
        assert Path(managed_path).exists(), imported

        uncovered_settings = api.photo_library_settings({})
        uncovered_status = uncovered_settings["backupPolicyStatus"]
        assert uncovered_status["counts"]["externalManagedAssets"] == 1, uncovered_status
        assert uncovered_status["counts"]["externalManagedAssetsRequiringBackup"] == 1, uncovered_status
        assert uncovered_status["counts"]["assetsRequiringExternalBackup"] == 1, uncovered_status
        uncovered_root = next(root for root in uncovered_status["rootCoverage"] if root["path"] == str(managed_root.resolve()))
        assert uncovered_root["requiresExternalBackup"] is True, uncovered_root

        covered_settings = api.save_photo_library_settings({
            "managedRootPolicy": {
                "path": str(managed_root.resolve()),
                "policy": {
                    "externalBackupCovered": True,
                    "externalBackupLabel": "External disk A",
                    "externalBackupCheckedAt": "2026-06-28T00:00:00Z",
                },
            }
        })
        covered_status = covered_settings["backupPolicyStatus"]
        assert covered_status["counts"]["externalManagedAssets"] == 1, covered_status
        assert covered_status["counts"]["externalManagedAssetsCovered"] == 1, covered_status
        assert covered_status["counts"]["externalManagedAssetsRequiringBackup"] == 0, covered_status
        assert covered_status["counts"]["assetsRequiringExternalBackup"] == 0, covered_status
        covered_root = next(root for root in covered_status["rootCoverage"] if root["path"] == str(managed_root.resolve()))
        assert covered_root["requiresExternalBackup"] is False, covered_root
        assert covered_root["externalBackupCovered"] is True, covered_root
        assert covered_root["externalBackupLabel"] == "External disk A", covered_root

        api.save_photo_library_settings({"forgetManagedRoot": str(managed_root)})
        bad_root = base / "blocked-managed-folder"
        bad_root.mkdir()
        api.save_photo_library_settings({
            "defaultManagedRoot": str(bad_root),
            "defaultStorageMode": "managed",
            "profileName": "Broken managed root",
        })
        os.chmod(bad_root, 0o555)

        try:
            settings = api.photo_library_settings({})
            broken_coverage = [
                root for root in settings["backupPolicyStatus"]["rootCoverage"]
                if root["path"] == str(bad_root.resolve())
            ]
            assert broken_coverage and broken_coverage[0]["issue"] == "Managed root folder is not writable.", settings
            assert settings["backupPolicyStatus"]["counts"]["managedRootProfileIssues"] == 1, settings
            assert settings["backupPolicyStatus"]["counts"]["managedAssetsOutsideProfiles"] == 1, settings

            result = api.photo_library_backup_check({"sampleLimit": 4})
            assert result["ok"] is True, result
            assert result["status"] == "warning", result
            counts = result["counts"]
            assert counts["managedAssets"] == 1, counts
            assert counts["missingOriginals"] == 0, counts
            assert counts["managedRootProfileIssues"] == 1, counts
            assert counts["managedAssetsOutsideProfiles"] == 1, counts
            assert result["samples"]["managedRootProfileIssues"][0]["path"] == str(bad_root.resolve()), result
            assert result["samples"]["managedRootProfileIssues"][0]["reason"] == "Managed root folder is not writable.", result
            assert result["samples"]["managedAssetsOutsideProfiles"][0]["sourcePath"] == managed_path, result
            assert any(check["id"] == "managed-root-profiles" and not check["ok"] for check in result["checks"]), result
            assert any("managed root profiles" in item.lower() for item in result["recommendations"]), result
        finally:
            os.chmod(bad_root, 0o755)
    print("ok Photos backup readiness reports managed-root profile drift")


def test_photo_root_profile_writes_block_duplicate_and_managed_overlap() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        parent = base / "managed-parent"
        child = parent / "child"
        child.mkdir(parents=True)
        api.save_photo_library_settings({
            "defaultManagedRoot": str(parent),
            "defaultStorageMode": "managed",
            "profileName": "Parent managed",
        })

        try:
            api.save_photo_library_settings({
                "defaultManagedRoot": str(child),
                "defaultStorageMode": "managed",
                "profileName": "Child managed",
            })
            assert False, "nested managed root should be rejected"
        except ValueError as exc:
            assert "cannot be nested" in str(exc), exc

        try:
            api.save_photo_library_settings({
                "libraryRootProfile": {
                    "path": str(parent),
                    "name": "Duplicate view root",
                }
            })
            assert False, "view root duplicating a managed root should be rejected"
        except ValueError as exc:
            assert "same folder" in str(exc), exc

        settings = api.photo_library_settings({})
        assert not settings.get("libraryRoots"), settings
        managed_paths = [root["path"] for root in settings["managedRoots"]]
        assert str(parent.resolve()) in managed_paths, settings
        assert str(child.resolve()) not in managed_paths, settings
    print("ok Photos root profile writes block duplicates and managed overlaps")


def test_photo_library_root_status_reports_overlap_and_symlink_alias() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        parent = base / "view-parent"
        child = parent / "child"
        child.mkdir(parents=True)
        api.save_photo_library_settings({
            "libraryRootProfile": {
                "path": str(parent),
                "name": "Parent view",
            }
        })
        api.save_photo_library_settings({
            "libraryRootProfile": {
                "path": str(child),
                "name": "Child view",
            }
        })

        settings = api.photo_library_settings({})
        profiles_by_path = {root["path"]: root for root in settings["libraryRoots"]}
        parent_profile = profiles_by_path[str(parent.resolve())]
        child_profile = profiles_by_path[str(child.resolve())]
        assert parent_profile["rootConflict"] is True, parent_profile
        assert child_profile["rootConflict"] is True, child_profile
        assert parent_profile["rootConflictKind"] == "nested", parent_profile
        assert child_profile["rootConflictKind"] == "nested", child_profile
        assert parent_profile["policyWarnings"][0]["kind"] == "overlap", parent_profile
        assert settings["rootPolicyStatus"]["status"] == "warning", settings
        assert settings["rootPolicyStatus"]["counts"]["overlaps"] >= 2, settings

        if hasattr(os, "symlink"):
            real = base / "real-view"
            alias = base / "alias-view"
            real.mkdir()
            try:
                os.symlink(real, alias)
            except (OSError, NotImplementedError):
                alias = None
            if alias is not None:
                raw = api.project.db.photo_library_settings()
                raw["libraryRoots"].extend([
                    {
                        "profileId": "real-view",
                        "name": "Real view",
                        "path": str(real),
                        "createdAt": "2026-06-29T00:00:00Z",
                        "updatedAt": "2026-06-29T00:00:00Z",
                    },
                    {
                        "profileId": "alias-view",
                        "name": "Alias view",
                        "path": str(alias),
                        "createdAt": "2026-06-29T00:00:00Z",
                        "updatedAt": "2026-06-29T00:00:00Z",
                    },
                ])
                with api.project.db.connect() as conn:
                    conn.execute(
                        """
                        INSERT INTO meta(key, value)
                        VALUES('photo_library_settings', ?)
                        ON CONFLICT(key) DO UPDATE SET value = excluded.value
                        """,
                        (json.dumps(raw),),
                    )
                alias_settings = api.photo_library_settings({})
                alias_profile = next(root for root in alias_settings["libraryRoots"] if root["profileId"] == "alias-view")
                assert alias_profile["rootConflict"] is True, alias_profile
                assert alias_profile["rootConflictKind"] == "symlink_alias", alias_profile
                assert alias_profile["policyWarnings"][0]["kind"] == "symlink", alias_profile
                assert alias_settings["rootPolicyStatus"]["counts"]["symlinkAliases"] >= 2, alias_settings
    print("ok Photos library root status reports overlap and symlink aliases")


