def test_photo_library_backup_check_reports_catalog_integrity_drift() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = base / "catalog-good.jpg"
        _write_exif_photo(photo)
        imported = api.import_photos(
            {
                "sourcePaths": [str(photo)],
                "storageMode": "referenced",
                "sourceLabel": "Catalog integrity",
            }
        )
        source_path = imported["importedPaths"][0]
        api.rebuild_photo_previews({"sourcePaths": [source_path], "force": True})
        asset = api.project.db.photo_asset_by_path(source_path)
        assert asset, asset
        album = api.save_photo_album({"name": "Catalog cover drift", "albumKind": "manual"})
        now = "2026-06-27T00:00:00Z"
        missing_asset_id = "missing-catalog-asset"
        with api.project.db.connect() as conn:
            conn.execute("PRAGMA foreign_keys=OFF")
            conn.execute(
                "INSERT INTO photo_asset_metadata(asset_id, updated_at) VALUES(?, ?)",
                (missing_asset_id, now),
            )
            conn.execute(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, 'accepted', 0.9, 0.8, 'manual', ?)
                """,
                (missing_asset_id, "missing-face", "Ghost Person", now),
            )
            conn.execute(
                "INSERT INTO photo_asset_keywords(asset_id, keyword_id, assigned_at) VALUES(?, ?, ?)",
                (asset["assetId"], "missing-keyword", now),
            )
            conn.execute(
                """
                INSERT INTO photo_asset_events(event_id, asset_id, event_type, event_at, actor, metadata_json)
                VALUES(?, ?, 'metadata_update', ?, 'test', '{}')
                """,
                ("missing-event", missing_asset_id, now),
            )
            conn.execute(
                """
                INSERT INTO photo_duplicate_groups(group_id, algorithm, signature, item_count, primary_asset_id, created_at, updated_at)
                VALUES(?, 'test', 'sig-missing', 1, ?, ?, ?)
                """,
                ("missing-duplicate-group", missing_asset_id, now, now),
            )
            conn.execute(
                """
                INSERT INTO photo_people_groups(group_id, name, member_people_json, excluded_people_json, member_pets_json, excluded_pets_json, key_asset_id, created_at, updated_at)
                VALUES(?, 'Broken group cover', '[]', '[]', '[]', '[]', ?, ?, ?)
                """,
                ("missing-people-group", missing_asset_id, now, now),
            )
            conn.execute(
                "UPDATE photo_albums SET cover_source_path = ?, updated_at = ? WHERE album_id = ?",
                (str((base / "missing-cover.jpg").resolve()), now, album["albumId"]),
            )

        result = api.photo_library_backup_check({"sampleLimit": 12})
        assert result["ok"] is True, result
        assert result["status"] == "warning", result
        counts = result["counts"]
        assert counts["missingOriginals"] == 0, counts
        assert counts["missingCachedPreviews"] == 0, counts
        assert counts["orphanAlbumItems"] == 0, counts
        assert counts["catalogIntegrityIssues"] == 7, counts
        assert any(check["id"] == "catalog-integrity" and not check["ok"] and check["severity"] == "warning" for check in result["checks"]), result
        sample_tables = {sample["table"] for sample in result["samples"]["catalogIntegrityIssues"]}
        assert {
            "photo_asset_metadata",
            "photo_asset_people",
            "photo_asset_keywords",
            "photo_asset_events",
            "photo_duplicate_groups",
            "photo_people_groups",
            "photo_albums",
        } <= sample_tables, result

        with api.project.db.connect() as conn:
            conn.execute("PRAGMA foreign_keys=OFF")
            conn.execute(
                "INSERT INTO photo_album_items(album_id, asset_id, position, added_at) VALUES(?, ?, 0, ?)",
                ("missing-album", missing_asset_id, now),
            )

        dry_run = api.photo_library_catalog_cleanup({"sampleLimit": 12})
        assert dry_run["applied"] is False, dry_run
        assert dry_run["ok"] is False, dry_run
        assert dry_run["status"] == "warning", dry_run
        assert dry_run["counts"]["catalogIntegrityIssues"] == 7, dry_run
        assert dry_run["counts"]["orphanAlbumItems"] == 1, dry_run
        assert dry_run["counts"]["cleanupCandidates"] == 8, dry_run
        assert dry_run["counts"]["cleanedRows"] == 0, dry_run
        assert dry_run["counts"]["remainingCandidates"] == 8, dry_run
        assert dry_run["samples"]["orphanAlbumItems"][0]["operation"] == "orphan-album-items", dry_run

        cleaned = api.photo_library_catalog_cleanup({"apply": True, "sampleLimit": 12})
        assert cleaned["applied"] is True, cleaned
        assert cleaned["ok"] is True, cleaned
        assert cleaned["status"] == "repaired", cleaned
        assert cleaned["counts"]["cleanupCandidates"] == 8, cleaned
        assert cleaned["counts"]["cleanedRows"] == 8, cleaned
        assert cleaned["counts"]["remainingCandidates"] == 0, cleaned
        assert any(operation["id"] == "broken-album-covers" and operation["cleaned"] == 1 for operation in cleaned["operations"]), cleaned

        repaired = api.photo_library_backup_check({"sampleLimit": 12})
        assert repaired["counts"]["catalogIntegrityIssues"] == 0, repaired
        assert repaired["counts"]["orphanAlbumItems"] == 0, repaired
        assert all(check["id"] != "catalog-integrity" or check["ok"] for check in repaired["checks"]), repaired
    print("ok Photos backup readiness reports catalog integrity drift")


def test_photo_library_backup_check_reports_missing_media_pair_files() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        live_still = base / "live-pair.jpg"
        live_motion = base / "live-pair.mov"
        raw_primary = base / "raw-pair.jpg"
        raw_sidecar = base / "raw-pair.dng"
        _write_exif_photo(live_still)
        live_motion.write_bytes(b"live motion")
        _write_exif_photo(raw_primary)
        raw_sidecar.write_bytes(b"raw companion")

        imported = api.import_photos({
            "sourcePaths": [str(live_still), str(raw_primary)],
            "storageMode": "referenced",
            "sourceLabel": "Missing media-pair backup check",
        })
        assert imported["importedCount"] == 2, imported
        api.rebuild_photo_previews({"sourcePaths": imported["importedPaths"], "force": True})

        live_asset = api.project.db.photo_asset_by_path(imported["importedPaths"][0])
        raw_asset = api.project.db.photo_asset_by_path(imported["importedPaths"][1])
        assert live_asset and live_asset["mediaKind"] == "live_photo", live_asset
        assert raw_asset, raw_asset
        assert Path(live_asset["metadata"]["livePhoto"]["pairedVideoPath"]).samefile(live_motion), live_asset
        with api.project.db.connect() as conn:
            raw_pair = conn.execute(
                """
                SELECT *
                FROM photo_media_pairs
                WHERE asset_id = ? AND pair_kind = 'raw_sidecar'
                LIMIT 1
                """,
                (raw_asset["assetId"],),
            ).fetchone()
        assert raw_pair is not None, raw_asset
        assert Path(raw_pair["related_source_path"]).samefile(raw_sidecar), dict(raw_pair)

        live_motion.unlink()
        raw_sidecar.unlink()

        result = api.photo_library_backup_check({"sampleLimit": 4})
        assert result["ok"] is True, result
        assert result["status"] == "warning", result
        counts = result["counts"]
        assert counts["missingOriginals"] == 0, counts
        assert counts["missingCachedPreviews"] == 0, counts
        assert counts["livePhotoAssets"] == 1, counts
        assert counts["pairedMotionFiles"] == 0, counts
        assert counts["missingPairedMotionFiles"] == 1, counts
        assert counts["nonLiveMediaPairRows"] == 1, counts
        assert counts["mediaPairRelatedFiles"] == 0, counts
        assert counts["missingMediaPairFiles"] == 1, counts
        paired_sample = result["samples"]["missingPairedMotionFiles"][0]
        assert paired_sample["sourcePath"] == str(live_still.resolve()), result
        assert paired_sample["pairedVideoPath"] == str(live_motion.resolve()), result
        media_pair_sample = result["samples"]["missingMediaPairFiles"][0]
        assert media_pair_sample["pairKind"] == "raw_sidecar", result
        assert media_pair_sample["sourcePath"] == str(raw_primary.resolve()), result
        assert media_pair_sample["relatedSourcePath"] == str(raw_sidecar.resolve()), result
        assert any(check["id"] == "media-pair-files" and not check["ok"] and check["severity"] == "warning" for check in result["checks"]), result
        assert any("media-pair companion" in item for item in result["recommendations"]), result

        dry_run = api.photo_library_catalog_cleanup({"sampleLimit": 4})
        assert dry_run["applied"] is False, dry_run
        assert dry_run["counts"]["staleGeneratedMediaPairs"] == 1, dry_run
        assert dry_run["counts"]["cleanupCandidates"] == 1, dry_run
        assert dry_run["samples"]["staleGeneratedMediaPairs"][0]["pairKind"] == "raw_sidecar", dry_run
        assert any(operation["id"] == "stale-generated-media-pairs" and operation["count"] == 1 for operation in dry_run["operations"]), dry_run

        cleaned = api.photo_library_catalog_cleanup({"apply": True, "sampleLimit": 4})
        assert cleaned["applied"] is True, cleaned
        assert cleaned["status"] == "repaired", cleaned
        assert cleaned["counts"]["staleGeneratedMediaPairs"] == 1, cleaned
        assert cleaned["counts"]["cleanedRows"] == 1, cleaned
        assert cleaned["counts"]["remainingCandidates"] == 0, cleaned
        assert any(operation["id"] == "stale-generated-media-pairs" and operation["cleaned"] == 1 for operation in cleaned["operations"]), cleaned
        with api.project.db.connect() as conn:
            remaining_pair = conn.execute(
                "SELECT COUNT(*) AS n FROM photo_media_pairs WHERE pair_id = ?",
                (raw_pair["pair_id"],),
            ).fetchone()
        assert int(remaining_pair["n"]) == 0, remaining_pair

        repaired = api.photo_library_backup_check({"sampleLimit": 4})
        assert repaired["counts"]["missingMediaPairFiles"] == 0, repaired
        assert repaired["counts"]["missingPairedMotionFiles"] == 1, repaired
    print("ok Photos backup readiness reports missing Live motion and media-pair companion files")


def test_photo_library_catalog_cleanup_dedupes_duplicate_asset_ids() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = base / "duplicate-asset-id.jpg"
        _write_exif_photo(photo)
        imported = api.import_photos(
            {
                "sourcePaths": [str(photo)],
                "storageMode": "referenced",
                "sourceLabel": "Duplicate asset id repair",
            }
        )
        source_path = imported["importedPaths"][0]
        api.rebuild_photo_previews({"sourcePaths": [source_path], "force": True})
        asset = api.project.db.photo_asset_by_path(source_path)
        assert asset, asset
        asset_id = asset["assetId"]
        with api.project.db.connect() as conn:
            conn.execute("PRAGMA foreign_keys=OFF")
            conn.execute("CREATE TABLE photo_assets_copy AS SELECT * FROM photo_assets")
            conn.execute("INSERT INTO photo_assets_copy SELECT * FROM photo_assets WHERE asset_id = ?", (asset_id,))
            conn.execute("DROP TABLE photo_assets")
            conn.execute("ALTER TABLE photo_assets_copy RENAME TO photo_assets")

        with api.project.db.connect() as conn:
            duplicate_count = conn.execute("SELECT COUNT(*) AS n FROM photo_assets WHERE asset_id = ?", (asset_id,)).fetchone()
        assert int(duplicate_count["n"]) == 2, duplicate_count

        result = api.photo_library_backup_check({"sampleLimit": 8})
        assert result["status"] == "warning", result
        assert result["counts"]["catalogIntegrityIssues"] == 1, result
        assert any(check["id"] == "catalog-integrity" and not check["ok"] for check in result["checks"]), result
        duplicate_samples = [sample for sample in result["samples"]["catalogIntegrityIssues"] if sample.get("table") == "photo_assets"]
        assert duplicate_samples and duplicate_samples[0]["duplicateRows"] == 2, result

        dry_run = api.photo_library_catalog_cleanup({"sampleLimit": 8})
        assert dry_run["counts"]["catalogIntegrityIssues"] == 1, dry_run
        assert dry_run["counts"]["cleanupCandidates"] == 1, dry_run
        assert dry_run["counts"]["remainingCandidates"] == 1, dry_run
        assert dry_run["samples"]["catalogIntegrityIssues"][0]["operation"] == "duplicate-photo-asset-ids", dry_run

        cleaned = api.photo_library_catalog_cleanup({"apply": True, "sampleLimit": 8})
        assert cleaned["status"] == "repaired", cleaned
        assert cleaned["counts"]["cleanedRows"] == 1, cleaned
        assert cleaned["counts"]["remainingCandidates"] == 0, cleaned
        assert any(operation["id"] == "duplicate-photo-asset-ids" and operation["cleaned"] == 1 for operation in cleaned["operations"]), cleaned
        with api.project.db.connect() as conn:
            repaired_count = conn.execute("SELECT COUNT(*) AS n FROM photo_assets WHERE asset_id = ?", (asset_id,)).fetchone()
        assert int(repaired_count["n"]) == 1, repaired_count
        repaired = api.photo_library_backup_check({"sampleLimit": 8})
        assert repaired["counts"]["catalogIntegrityIssues"] == 0, repaired
    print("ok Photos catalog cleanup dedupes duplicate asset ids")


def test_photo_backup_restore_rehearsal_exports_verifies_and_restores() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        missing_backup = api.photo_backup_restore_rehearsal({"createBackup": False, "sampleLimit": 4})
        assert missing_backup["ok"] is False, missing_backup
        assert missing_backup["status"] == "attention", missing_backup
        assert any(check["id"] == "workspace-backup-available" and not check["ok"] for check in missing_backup["checks"]), missing_backup

        source = base / "restore-rehearsal.jpg"
        _write_exif_photo(source)
        managed_root = base / "workspace" / "photo-library" / "managed-rehearsal"
        imported = api.import_photos(
            {
                "sourcePaths": [str(source)],
                "storageMode": "managed",
                "managedRoot": str(managed_root),
                "sourceLabel": "Restore rehearsal",
            }
        )
