        assert rendered["hasStack"] is False, rendered
        assert rendered["clonedAlbums"] == 1, rendered
        assert rendered["clonedPeople"] == 1, rendered
        assert rendered["clonedVersions"] == 0, rendered
        with Image.open(duplicate_path) as baked:
            assert max(baked.size) == 8, baked.size
            red, green, blue = baked.convert("RGB").getpixel((baked.width // 2, baked.height // 2))
            assert red > 90 and green > 80 and red > blue, (red, green, blue)

