def test_photo_recovered_failure_save_and_delete_actions() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)

        missing_save = base / "missing-save.jpg"
        recovered_save = base / "recovered-save.jpg"
        recovered_save.write_bytes(b"recovered save bytes")
        api.import_photos(
            {
                "sourcePaths": [str(missing_save)],
                "storageMode": "referenced",
                "sourceLabel": "Recoverable save",
            }
        )
        save_failure = api.list_photo_import_failures({})["failures"][0]
        with api.project.db.connect() as conn:
            conn.execute(
                "UPDATE photo_import_failures SET recovered_path = ? WHERE failure_id = ?",
                (str(recovered_save), save_failure["failureId"]),
            )
        save_failure = api.list_photo_import_failures({})["failures"][0]
        assert save_failure["recoveredPath"] == str(recovered_save), save_failure
        saved = api.save_recovered_photo_import_failure({"failureId": save_failure["failureId"]})
        assert saved["saved"] is True, saved
        assert saved["deleted"] is False, saved
        assert saved["dismissedFailure"]["dismissed"] is True, saved
        import_result = saved["importResult"]
        assert import_result["storageMode"] == "managed", import_result
        assert import_result["importedCount"] == 1, import_result
        saved_path = Path(import_result["importedPaths"][0])
        assert saved_path.exists(), import_result
        assert saved_path.read_bytes() == recovered_save.read_bytes()
        assert api.list_photo_import_failures({})["total"] == 0
        folders_after_save = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders_after_save["recovered"]["count"] == 0, folders_after_save

        missing_delete = base / "missing-delete.jpg"
        recovered_delete = base / "recovered-delete.jpg"
        recovered_delete.write_bytes(b"delete me")
        api.import_photos(
            {
                "sourcePaths": [str(missing_delete)],
                "storageMode": "referenced",
                "sourceLabel": "Recoverable delete",
            }
        )
        delete_failure = api.list_photo_import_failures({})["failures"][0]
        with api.project.db.connect() as conn:
            conn.execute(
                "UPDATE photo_import_failures SET recovered_path = ? WHERE failure_id = ?",
                (str(recovered_delete), delete_failure["failureId"]),
            )
        delete_failure = api.list_photo_import_failures({})["failures"][0]
        deleted = api.delete_recovered_photo_import_failure({"failureId": delete_failure["failureId"]})
        assert deleted["saved"] is False, deleted
        assert deleted["deleted"] is True, deleted
        assert deleted["dismissedFailure"]["dismissed"] is True, deleted
        assert not recovered_delete.exists()
        assert api.list_photo_import_failures({})["total"] == 0
    print("ok recovered import failure save/delete actions")


def test_photo_import_failure_rerecord_preserves_first_failure_timestamp() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        source = str(Path(tmp) / "missing-again.jpg")
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_import_sessions(
                    import_id, source_kind, storage_mode, source_label, root_path,
                    status, started_at, completed_at, updated_at, imported_count, failed_count, metadata_json
                ) VALUES(?, 'folder', 'referenced', 'Failure timestamp test', ?, 'completed', ?, ?, ?, 0, 1, '{}')
                """,
                (
                    "import-preserve-created",
                    str(Path(tmp)),
                    "2026-07-07T00:00:00Z",
                    "2026-07-07T00:00:00Z",
                    "2026-07-07T00:00:00Z",
                ),
            )
            api.project.db._record_photo_import_failure(
                conn,
                import_id="import-preserve-created",
                source_path=source,
                reason="first failure",
            )
            first = api.project.db.list_photo_import_failures(import_id="import-preserve-created", conn=conn)[0]
            api.project.db._record_photo_import_failure(
                conn,
                import_id="import-preserve-created",
                source_path=source,
                reason="second failure",
                recovered_path=str(Path(tmp) / "recovered.jpg"),
            )
            second = api.project.db.list_photo_import_failures(import_id="import-preserve-created", conn=conn)[0]
        assert second["failureId"] == first["failureId"], second
        assert second["reason"] == "second failure", second
        assert second["recoveredPath"].endswith("recovered.jpg"), second
        assert second["createdAt"] == first["createdAt"], (first, second)
    print("ok photo import failure re-record preserves first failure timestamp")


def test_photo_import_failure_retry_repairs_original_source() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)

        missing = base / "retry-missing.jpg"
        initial = api.import_photos(
            {
                "sourcePaths": [str(missing)],
                "storageMode": "referenced",
                "sourceLabel": "Retry missing original",
            }
        )
        assert initial["importedCount"] == 0, initial
        assert initial["failedCount"] == 1, initial
        failure = api.list_photo_import_failures({})["failures"][0]
        try:
            api.retry_photo_import_failure({"failureId": failure["failureId"]})
        except ValueError as exc:
            assert "still missing" in str(exc)
        else:
            raise AssertionError("retry should require the original source to exist")
        assert api.list_photo_import_failures({})["total"] == 1

        missing.write_bytes(b"retry source bytes")
        retried = api.retry_photo_import_failure({"failureId": failure["failureId"]})
        assert retried["retried"] is True, retried
        assert retried["saved"] is True, retried
        assert retried["storageMode"] == "referenced", retried
        assert retried["dismissedFailure"]["dismissed"] is True, retried
        retry_result = retried["importResult"]
        assert retry_result["importedCount"] == 1, retry_result
        assert retry_result["failedCount"] == 0, retry_result
        assert retry_result["importedPaths"] == [str(missing.resolve())], retry_result
        assert api.project.db.photo_asset_by_path(str(missing.resolve())), retry_result
        assert api.list_photo_import_failures({})["total"] == 0

        managed_root = base / "managed-root"
        api.save_photo_library_settings(
            {
                "defaultManagedRoot": str(managed_root),
                "defaultStorageMode": "managed",
                "profileName": "Retry managed",
            }
        )
        missing_managed = base / "retry-managed.jpg"
        api.import_photos(
            {
                "sourcePaths": [str(missing_managed)],
                "storageMode": "managed",
                "sourceLabel": "Retry managed original",
            }
        )
        managed_failure = api.list_photo_import_failures({})["failures"][0]
        missing_managed.write_bytes(b"managed retry source")
        managed_retried = api.retry_photo_import_failure({"failureId": managed_failure["failureId"]})
        assert managed_retried["storageMode"] == "managed", managed_retried
        managed_result = managed_retried["importResult"]
        assert managed_result["importedCount"] == 1, managed_result
        managed_path = Path(managed_result["importedPaths"][0])
        assert managed_path.exists(), managed_result
        assert managed_path.read_bytes() == missing_managed.read_bytes()
        assert str(managed_path).startswith(str(managed_root.resolve())), managed_result
        assert api.list_photo_import_failures({})["total"] == 0
    print("ok failed photo import retry repairs original sources")


def test_photo_recovered_orphan_scan_surfaces_unindexed_managed_files() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        managed_root = base / "managed-root"
        api.save_photo_library_settings(
            {
                "defaultManagedRoot": str(managed_root),
                "defaultStorageMode": "managed",
                "profileName": "Managed recovery",
            }
        )

        orphan = managed_root / "lost" / "orphan.jpg"
        orphan.parent.mkdir(parents=True)
        orphan.write_bytes(b"orphan bytes")
        outside_root = base / "outside-managed-root"
        outside_orphan = outside_root / "outside-orphan.jpg"
        outside_orphan.parent.mkdir(parents=True)
        outside_orphan.write_bytes(b"outside orphan bytes")
        ignored = managed_root / "lost" / "notes.txt"
        ignored.write_text("not a photo", encoding="utf-8")
        indexed = managed_root / "already-indexed.jpg"
        indexed.write_bytes(b"already indexed")
        api.import_photos({"sourcePaths": [str(indexed)], "storageMode": "referenced", "sourceLabel": "Indexed managed file"})

        preview = api.scan_photo_recovered_orphans({"roots": [str(managed_root), str(outside_root)], "libraryRoot": str(managed_root), "dryRun": True})
        assert preview["dryRun"] is True, preview
        assert preview["libraryRoot"] == str(managed_root.resolve()), preview
        assert preview["orphanCandidates"] == 1, preview
        assert preview["recorded"] == 0, preview
        assert preview["roots"] == [str(managed_root.resolve())], preview
        assert preview["failures"][0]["recoveredPath"] == str(orphan.resolve()), preview
        assert api.list_photo_import_failures({})["total"] == 0

        scanned = api.scan_photo_recovered_orphans({})
        assert scanned["recorded"] == 1, scanned
        assert scanned["skippedExistingAssets"] == 1, scanned
        failure = api.list_photo_import_failures({})["failures"][0]
        assert failure["importId"] == "orphan_recovery", failure
        assert failure["sourcePath"] == str(orphan.resolve()), failure
        assert failure["recoveredPath"] == str(orphan.resolve()), failure
        assert failure["sourceName"] == "orphan.jpg", failure

        duplicate_scan = api.scan_photo_recovered_orphans({})
        assert duplicate_scan["recorded"] == 0, duplicate_scan
        assert duplicate_scan["skippedExistingFailures"] == 1, duplicate_scan
        assert api.list_photo_import_failures({})["total"] == 1

        saved = api.save_recovered_photo_import_failure({"failureId": failure["failureId"]})
        assert saved["saved"] is True, saved
        assert saved["importResult"]["importedCount"] == 1, saved
        saved_path = Path(saved["importResult"]["importedPaths"][0])
        assert saved_path.exists(), saved
        assert saved_path.read_bytes() == orphan.read_bytes()
        assert api.list_photo_import_failures({})["total"] == 0
    print("ok recovered orphan scan surfaces unindexed managed files")


def test_photo_recovered_cleanup_policy_handles_stale_orphan_rows() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        managed_root = base / "managed"
        outside_root = base / "outside-managed"
        managed_root.mkdir()
        outside_root.mkdir()
        missing_orphan = managed_root / "missing-orphan.jpg"
        indexed_orphan = managed_root / "indexed-orphan.jpg"
        old_orphan = managed_root / "old-orphan.jpg"
        outside_orphan = outside_root / "outside-orphan.jpg"
        for path in (missing_orphan, indexed_orphan, old_orphan, outside_orphan):
            _write_exif_photo(path)

        scanned = api.scan_photo_recovered_orphans({"roots": [str(managed_root), str(outside_root)], "limit": 10})
        assert scanned["recorded"] == 4, scanned
        failures = api.list_photo_import_failures({"limit": 10})["failures"]
        failures_by_path = {failure["recoveredPath"]: failure for failure in failures}
        assert set(failures_by_path) == {str(missing_orphan.resolve()), str(indexed_orphan.resolve()), str(old_orphan.resolve()), str(outside_orphan.resolve())}, failures

        missing_orphan.unlink()
        outside_orphan.unlink()
        api.import_photos({"sourcePaths": [str(indexed_orphan)], "storageMode": "referenced", "sourceLabel": "Already saved orphan"})
        old_failure = failures_by_path[str(old_orphan.resolve())]
        api.dismiss_photo_import_failure({"failureId": old_failure["failureId"]})
        with api.project.db.connect() as conn:
            conn.execute(
                "UPDATE photo_import_failures SET dismissed_at = ? WHERE failure_id = ?",
                ("2000-01-01T00:00:00Z", old_failure["failureId"]),
            )

        preview = api.photo_recovered_cleanup({"libraryRoot": str(managed_root), "retentionDays": 1, "sampleLimit": 8})
        assert preview["applied"] is False, preview
        assert preview["libraryRoot"] == str(managed_root.resolve()), preview
        assert preview["status"] == "warning", preview
        assert preview["counts"]["cleanupCandidates"] == 3, preview
        assert preview["counts"]["missingRecoveredOrphans"] == 1, preview
        assert preview["counts"]["indexedRecoveredOrphans"] == 1, preview
        assert preview["counts"]["expiredDismissedOrphans"] == 1, preview
        assert preview["counts"]["fileDeleteCandidates"] == 1, preview

        cleaned = api.photo_recovered_cleanup({"libraryRoot": str(managed_root), "apply": True, "retentionDays": 1, "deleteRecoveredFiles": False, "sampleLimit": 8})
        assert cleaned["status"] == "repaired", cleaned
        assert cleaned["counts"]["rowsDismissed"] == 2, cleaned
        assert cleaned["counts"]["rowsDeleted"] == 1, cleaned
        assert cleaned["counts"]["filesDeleted"] == 0, cleaned
        assert old_orphan.exists(), cleaned
        remaining_active = api.list_photo_import_failures({})["failures"]
        assert len(remaining_active) == 1, remaining_active
        assert remaining_active[0]["recoveredPath"] == str(outside_orphan.resolve()), remaining_active
        dismissed_rows = [
            failure
            for failure in api.list_photo_import_failures({"includeDismissed": True, "limit": 10})["failures"]
            if failure.get("dismissedAt")
        ]
        assert len(dismissed_rows) == 2, dismissed_rows
    print("ok recovered cleanup policy handles stale orphan rows")


def test_photo_recovered_cleanup_can_delete_expired_recovered_files_when_requested() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        managed_root = base / "managed"
        managed_root.mkdir()
        old_orphan = managed_root / "old-file-orphan.jpg"
        _write_exif_photo(old_orphan)

        scanned = api.scan_photo_recovered_orphans({"roots": [str(managed_root)], "limit": 10})
        assert scanned["recorded"] == 1, scanned
        failure = api.list_photo_import_failures({"limit": 10})["failures"][0]
        api.dismiss_photo_import_failure({"failureId": failure["failureId"]})
        with api.project.db.connect() as conn:
            conn.execute(
                "UPDATE photo_import_failures SET dismissed_at = ? WHERE failure_id = ?",
                ("2000-01-01T00:00:00Z", failure["failureId"]),
            )

        preview = api.photo_recovered_cleanup({"retentionDays": 1, "sampleLimit": 8})
        assert preview["counts"]["expiredDismissedOrphans"] == 1, preview
        assert preview["counts"]["fileDeleteCandidates"] == 1, preview
        assert old_orphan.exists(), preview

        cleaned = api.photo_recovered_cleanup({"apply": True, "retentionDays": 1, "deleteRecoveredFiles": True, "sampleLimit": 8})
