def test_photo_import_session_archive_hides_and_restores_history_without_deleting_assets() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        first = base / "archive-first.jpg"
        second = base / "archive-second.jpg"
        first.write_bytes(b"first import")
        second.write_bytes(b"second import")
        first_result = api.import_photos({
            "sourcePaths": [str(first)],
            "storageMode": "referenced",
            "sourceKind": "folder",
            "sourceLabel": "First import",
        })
        second_result = api.import_photos({
            "sourcePaths": [str(second)],
            "storageMode": "referenced",
            "sourceKind": "mail",
            "sourceLabel": "Second import",
        })
        first_id = first_result["importId"]
        second_id = second_result["importId"]
        first_path = first_result["importedPaths"][0]
        second_path = second_result["importedPaths"][0]

        archived = api.archive_photo_import_sessions({"importIds": [second_id], "reason": "Clean imported mail history"})
        assert archived["archived"] is True, archived
        assert archived["changed"] == 1, archived
        assert archived["sessions"][0]["archived"] is True, archived
        assert archived["sessions"][0]["archivedReason"] == "Clean imported mail history", archived

        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["lastImport"]["importSession"]["importId"] == first_id, folders["lastImport"]
        assert [session["importId"] for session in folders["imports"]["importSessions"]] == [first_id], folders["imports"]
        assert folders["imports"]["archivedImportSessionCount"] == 1, folders["imports"]
        assert [session["importId"] for session in folders["imports"]["archivedImportSessions"]] == [second_id], folders["imports"]
        assert folders["imports"]["archivedImportSessions"][0]["archivedAt"], folders["imports"]
        assert folders["imports"]["count"] == 1, folders["imports"]

        all_page = api.list_photo_folder_items({"folderId": "all", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in all_page["items"]] == [first_path, second_path], all_page

        restored = api.archive_photo_import_sessions({"importIds": [second_id], "archive": False})
        assert restored["archived"] is False, restored
        assert restored["changed"] == 1, restored
        assert restored["sessions"][0]["archived"] is False, restored
        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["lastImport"]["importSession"]["importId"] == second_id, folders["lastImport"]
        assert [session["importId"] for session in folders["imports"]["importSessions"]] == [second_id, first_id], folders["imports"]

        bulk = api.archive_photo_import_sessions({"importIds": [first_id, second_id]})
        assert bulk["changed"] == 2, bulk
        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["imports"]["importSessionCount"] == 0, folders["imports"]
        assert folders["imports"]["archivedImportSessionCount"] == 2, folders["imports"]
        all_after_bulk = api.list_photo_folder_items({"folderId": "all", "previewBudget": 0})
        assert all_after_bulk["total"] == 2, all_after_bulk
        assert api.project.db.photo_asset_by_path(second_path), second_path
    print("ok photo import session archive hides/restores history without deleting assets")


def test_photo_recently_viewed_and_shared_event_collections() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        first = str(base / "first.jpg")
        second = str(base / "second.jpg")
        third = str(base / "third.jpg")
        for path in (first, second, third):
            Path(path).write_bytes(f"photo:{path}".encode("utf-8"))
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (first, second, third):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")

        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["recentlyViewed"]["count"] == 0, folders["recentlyViewed"]
        assert folders["recentlyShared"]["count"] == 0, folders["recentlyShared"]

        viewed = api.record_photo_asset_event({
            "eventType": "viewed",
            "sourcePaths": [first, second, third, first],
            "metadata": {"surface": "photos-lightbox", "session": "unit"},
        })
        assert viewed["requested"] == 3, viewed
        assert viewed["recorded"] == 3, viewed
        assert viewed["summary"]["count"] == 3, viewed
        assert viewed["summary"]["coverSourcePath"] in {first, second, third}, viewed
        first_asset = api.project.db.photo_asset_by_path(first)
        second_asset = api.project.db.photo_asset_by_path(second)
        third_asset = api.project.db.photo_asset_by_path(third)
        now = datetime.utcnow().replace(microsecond=0)
        first_event_at = (now - timedelta(hours=2)).isoformat(timespec="seconds") + "Z"
        second_event_at = (now - timedelta(hours=1)).isoformat(timespec="seconds") + "Z"
        old_event_at = (now - timedelta(days=45)).isoformat(timespec="seconds") + "Z"
        with api.project.db.connect() as conn:
            conn.execute("UPDATE photo_asset_events SET event_at = ? WHERE asset_id = ?", (first_event_at, first_asset["assetId"]))
            conn.execute("UPDATE photo_asset_events SET event_at = ? WHERE asset_id = ?", (second_event_at, second_asset["assetId"]))
            conn.execute("UPDATE photo_asset_events SET event_at = ? WHERE asset_id = ?", (old_event_at, third_asset["assetId"]))

        viewed_page = api.list_photo_folder_items({"folderId": "recentlyViewed", "previewBudget": 0})
        assert viewed_page["total"] == 2, viewed_page
        assert [item["sourcePath"] for item in viewed_page["items"]] == [second, first], viewed_page["items"]
        viewed_second = viewed_page["items"][0]
        assert viewed_second["eventType"] == "viewed", viewed_second
        assert viewed_second["eventAt"] == second_event_at, viewed_second
        assert viewed_second["eventMetadata"]["surface"] == "photos-lightbox", viewed_second
        assert viewed_second["eventMetadata"]["session"] == "unit", viewed_second

        api.update_photo_asset_metadata({"sourcePath": second, "hidden": True})
        viewed_after_hide = api.list_photo_folder_items({"folderId": "recentlyViewed", "previewBudget": 0})
        assert [item["sourcePath"] for item in viewed_after_hide["items"]] == [first], viewed_after_hide["items"]
        assert {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}["recentlyViewed"]["count"] == 1

        original_asset_entries = api._photo_asset_entries

        def fail_event_summary_assembly(utility: str = "", *_args: Any, **_kwargs: Any) -> list[dict[str, Any]]:
            if utility in {"recentlyViewed", "recentlyShared"}:
                raise AssertionError(f"{utility} rail summary should use event SQL counts, not full Python assembly.")
            return original_asset_entries(utility)

        api._photo_asset_entries = fail_event_summary_assembly
        try:
            event_folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
            assert event_folders["recentlyViewed"]["count"] == 1, event_folders
            assert event_folders["recentlyShared"]["count"] == 0, event_folders
        finally:
            api._photo_asset_entries = original_asset_entries

        keep_all_settings = api.photo_library_settings({})["localSettings"]
        api.save_photo_library_settings({
            "localSettings": {
                **keep_all_settings,
                "recentActivityRetentionDays": 0,
            }
        })
        viewed_keep_all = api.list_photo_folder_items({"folderId": "recentlyViewed", "previewBudget": 0})
        assert [item["sourcePath"] for item in viewed_keep_all["items"]] == [first, third], viewed_keep_all["items"]
        assert {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}["recentlyViewed"]["count"] == 2
        api.save_photo_library_settings({
            "localSettings": {
                **api.photo_library_settings({})["localSettings"],
                "recentActivityRetentionDays": 30,
            }
        })

        exported = api.export_photo_selection([first, third], base / "exports")
        assert exported["counts"]["copied"] == 2, exported
        assert exported["sharedEvent"]["recorded"] == 2, exported
        shared_page = api.list_photo_folder_items({"folderId": "recentlyShared", "previewBudget": 0})
        assert shared_page["total"] == 2, shared_page
        assert {item["sourcePath"] for item in shared_page["items"]} == {first, third}, shared_page["items"]
        shared_by_source = {item["sourcePath"]: item for item in shared_page["items"]}
        assert shared_by_source[first]["eventType"] == "shared", shared_by_source
        assert shared_by_source[first]["eventMetadata"]["action"] == "export", shared_by_source
        assert "/exports/" in str(shared_by_source[first]["eventMetadata"]["bundlePath"]), shared_by_source
        api._photo_asset_entries = fail_event_summary_assembly
        try:
            shared_folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
            assert shared_folders["recentlyShared"]["count"] == 2, shared_folders
        finally:
            api._photo_asset_entries = original_asset_entries
    print("ok photo recently viewed/shared event collections")


