def test_photo_preview_rebuild_repairs_cached_previews() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = base / "preview-repair.jpg"
        _write_exif_photo(photo)
        source_path = str(photo.resolve())
        api.import_photos({"sourcePaths": [str(photo)], "storageMode": "referenced", "sourceLabel": "Preview repair"})

        page = api.list_photo_folder_items({"folderId": "all", "previewBudget": 1})
        preview_path = Path(page["items"][0]["previewPath"])
        assert preview_path.exists(), page
        preview_path.write_bytes(b"stale preview")

        dry_run = api.rebuild_photo_previews({"sourcePaths": [source_path], "dryRun": True})
        assert dry_run["dryRun"] is True, dry_run
        assert dry_run["rebuilt"][0]["wouldRemove"] is True, dry_run
        assert preview_path.read_bytes() == b"stale preview"

        rebuilt = api.rebuild_photo_previews({"sourcePaths": [source_path], "force": True})
        assert rebuilt["generatedPreviews"] == 1, rebuilt
        assert rebuilt["removedPreviewFiles"] == 1, rebuilt
        rebuilt_path = Path(rebuilt["rebuilt"][0]["previewPath"])
        assert rebuilt_path == preview_path, rebuilt
        assert rebuilt_path.exists(), rebuilt
        assert rebuilt_path.read_bytes() != b"stale preview"

        folder_rebuild = api.rebuild_photo_previews({"folderId": "all", "limit": 10})
        assert folder_rebuild["considered"] == 1, folder_rebuild
        assert folder_rebuild["generatedPreviews"] == 1, folder_rebuild
    print("ok photo preview rebuild repairs cached previews")


def test_photo_library_preview_sweep_repairs_missing_cached_previews() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        ready = base / "preview-ready.jpg"
        missing_preview = base / "preview-missing.jpg"
        _write_exif_photo(ready)
        _write_exif_photo(missing_preview)
        imported = api.import_photos({
            "sourcePaths": [str(ready), str(missing_preview)],
            "storageMode": "referenced",
            "sourceLabel": "Preview sweep",
        })
        ready_path = imported["importedPaths"][0]
        missing_path = imported["importedPaths"][1]
        ready_preview = api.project.preview_path_for(ready_path, create=True)
        assert ready_preview and Path(ready_preview).exists(), ready_preview
        assert api.project.preview_path_for(missing_path, create=False) is None

        dry_run = api.photo_library_preview_sweep({"dryRun": True, "limit": 10, "sampleLimit": 4})
        assert dry_run["dryRun"] is True, dry_run
        assert dry_run["status"] == "warning", dry_run
        assert dry_run["counts"]["eligibleAssets"] == 2, dry_run
        assert dry_run["counts"]["cachedPreviews"] == 1, dry_run
        assert dry_run["counts"]["missingCachedPreviews"] == 1, dry_run
        assert dry_run["counts"]["selectedAssets"] == 1, dry_run
        assert dry_run["counts"]["generatedPreviews"] == 0, dry_run
        assert dry_run["samples"]["missingCachedPreviews"][0]["sourcePath"] == missing_path, dry_run
        assert dry_run["history"][0]["dryRun"] is True, dry_run
        assert api.project.preview_path_for(missing_path, create=False) is None

        repaired = api.photo_library_preview_sweep({"limit": 10, "sampleLimit": 4})
        assert repaired["dryRun"] is False, repaired
        assert repaired["status"] == "repaired", repaired
        assert repaired["counts"]["generatedPreviews"] == 1, repaired
        assert repaired["counts"]["remainingMissingCachedPreviews"] == 0, repaired
        assert repaired["history"][0]["generatedPreviews"] == 1, repaired
        assert api.project.preview_path_for(missing_path, create=False), repaired

        backup = api.photo_library_backup_check({"sampleLimit": 4})
        assert backup["counts"]["missingCachedPreviews"] == 0, backup
    print("ok Photos preview sweep repairs missing cached previews")


def test_photo_library_preview_sweep_respects_library_root_scope() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alpha_root = base / "alpha-previews"
        beta_root = base / "beta-previews"
        alpha_root.mkdir()
        beta_root.mkdir()
        alpha = alpha_root / "alpha-ready.jpg"
        beta = beta_root / "beta-needs-preview.jpg"
        _write_exif_photo(alpha)
        _write_exif_photo(beta)
        imported = api.import_photos({
            "sourcePaths": [str(alpha), str(beta)],
            "storageMode": "referenced",
            "sourceLabel": "Scoped preview roots",
        })
        alpha_path = imported["importedPaths"][0]
        beta_path = imported["importedPaths"][1]
        alpha_root_path = str(alpha_root.resolve())
        beta_root_path = str(beta_root.resolve())
        alpha_preview = api.project.preview_path_for(alpha_path, create=True)
        assert alpha_preview and Path(alpha_preview).exists(), alpha_preview
        assert api.project.preview_path_for(beta_path, create=False) is None

        alpha_dry_run = api.photo_library_preview_sweep({
            "dryRun": True,
            "limit": 10,
            "sampleLimit": 4,
            "libraryRoot": alpha_root_path,
        })
        assert alpha_dry_run["libraryRoot"] == alpha_root_path, alpha_dry_run
        assert alpha_dry_run["scope"]["label"] == alpha_root.name, alpha_dry_run
        assert alpha_dry_run["counts"]["assets"] == 1, alpha_dry_run
        assert alpha_dry_run["counts"]["eligibleAssets"] == 1, alpha_dry_run
        assert alpha_dry_run["counts"]["missingCachedPreviews"] == 0, alpha_dry_run
        assert alpha_dry_run["counts"]["selectedAssets"] == 0, alpha_dry_run
        assert alpha_dry_run["history"][0]["libraryRoot"] == alpha_root_path, alpha_dry_run

        beta_dry_run = api.photo_library_preview_sweep({
            "dryRun": True,
            "limit": 10,
            "sampleLimit": 4,
            "libraryRoot": beta_root_path,
        })
        assert beta_dry_run["libraryRoot"] == beta_root_path, beta_dry_run
        assert beta_dry_run["counts"]["assets"] == 1, beta_dry_run
        assert beta_dry_run["counts"]["eligibleAssets"] == 1, beta_dry_run
        assert beta_dry_run["counts"]["missingCachedPreviews"] == 1, beta_dry_run
        assert beta_dry_run["counts"]["selectedAssets"] == 1, beta_dry_run
        assert beta_dry_run["samples"]["missingCachedPreviews"][0]["sourcePath"] == beta_path, beta_dry_run
        assert beta_dry_run["history"][0]["libraryRoot"] == beta_root_path, beta_dry_run
        assert api.project.preview_path_for(beta_path, create=False) is None

        beta_repaired = api.photo_library_preview_sweep({
            "limit": 10,
            "sampleLimit": 4,
            "libraryRoot": beta_root_path,
        })
        assert beta_repaired["counts"]["generatedPreviews"] == 1, beta_repaired
        assert beta_repaired["counts"]["remainingMissingCachedPreviews"] == 0, beta_repaired
        assert beta_repaired["history"][0]["libraryRoot"] == beta_root_path, beta_repaired
        assert api.project.preview_path_for(beta_path, create=False), beta_repaired
    print("ok Photos preview sweep scopes missing previews to the active library root")


