def test_smart_album_people_rules_read_candidate_backed_photo_assets_without_scan_manifest() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice = str(base / "alice.jpg")
        together = str(base / "alice-and-bob.jpg")
        bob = str(base / "bob.jpg")
        pending = str(base / "pending-alice.jpg")
        rejected = str(base / "rejected-alice.jpg")
        unknown = str(base / "unknown-cluster.jpg")
        video = str(base / "alice-video.mov")
        confident = float(api.project.config.thresholds.confident)
        api.project.db.upsert_candidates(
            [
                _candidate("a1", "Alice", alice, status="accepted", score=0.98, capture_date="2024-04-01"),
                _candidate("a2", "Alice", together, status="accepted", score=0.97, capture_date="2024-04-02"),
                _candidate("b2", "Bob", together, status="accepted", score=0.96, capture_date="2024-04-02"),
                _candidate("b1", "Bob", bob, status="accepted", score=0.95, capture_date="2024-04-03"),
                _candidate("p1", "Alice", pending, status="pending", score=0.10, quality=0.92, capture_date="2024-04-03"),
                _candidate("r1", "Alice", rejected, status="rejected", score=confident + 0.3, capture_date="2024-04-04"),
                _candidate("u1", "Unmatched cluster 7", unknown, status="uncertain", score=0.42, quality=0.4, capture_date="2024-04-05"),
                _candidate("v1", "Video Person", video, status="accepted", score=0.91, capture_date="2024-04-06", media_kind="video", media_source_path=video),
            ]
        )
        assert api.project.db.count_scan_media() == 0

        album = api.save_photo_album(
            {
                "name": "Alice without Bob",
                "includePeople": ["Alice"],
                "excludePeople": ["Bob"],
                "coverSourcePath": together,
            }
        )
        assert album["count"] == 1, album
        assert {item["code"] for item in album["validation"]} == {"cover-mismatch"}, album

        bob_album = api.save_photo_album({"name": "Bob smart", "includePeople": ["Bob"]})
        pending_album = api.save_photo_album(
            {
                "name": "Pending high quality",
                "albumKind": "smart",
                "rules": {"statuses": ["pending"], "minQuality": 0.9},
            }
        )
        assert pending_album["count"] == 1, pending_album
        unknown_album = api.save_photo_album(
            {
                "name": "Persisted unknown clusters",
                "albumKind": "smart",
                "rules": {"unknownOnly": True},
            }
        )
        assert unknown_album["count"] == 1, unknown_album
        unknown_dsl_album = api.save_photo_album(
            {
                "name": "Persisted unknown DSL",
                "albumKind": "smart",
                "rules": {"op": "all", "conditions": [{"field": "unknown", "operator": "is", "value": True}]},
            }
        )
        assert unknown_dsl_album["count"] == 1, unknown_dsl_album
        video_frames_album = api.save_photo_album(
            {
                "name": "Persisted video frames",
                "albumKind": "smart",
                "rules": {"hasVideoFrames": True},
            }
        )
        assert video_frames_album["count"] == 1, video_frames_album
        video_frames_dsl_album = api.save_photo_album(
            {
                "name": "Persisted video frames DSL",
                "albumKind": "smart",
                "rules": {"op": "all", "conditions": [{"field": "hasVideoFrames", "operator": "is", "value": True}]},
            }
        )
        assert video_frames_dsl_album["count"] == 1, video_frames_dsl_album
        dsl_album = api.save_photo_album(
            {
                "name": "Strong reviewed DSL",
                "albumKind": "smart",
                "rules": {
                    "queryDsl": {
                        "op": "all",
                        "conditions": [
                            {"field": "status", "operator": "isNot", "value": "rejected"},
                            {"field": "score", "operator": "greaterThan", "value": 0.975},
                            {"field": "quality", "operator": "atLeast", "value": 0.9},
                        ],
                    },
                },
            }
        )
        assert dsl_album["count"] == 1, dsl_album

        original_album_items = api._photo_album_items
        original_all_entries = api._all_photo_entries
        original_asset_entries = api._photo_asset_entries
        sql_album_ids = {
            album["albumId"],
            bob_album["albumId"],
            pending_album["albumId"],
            unknown_album["albumId"],
            unknown_dsl_album["albumId"],
            video_frames_album["albumId"],
            video_frames_dsl_album["albumId"],
            dsl_album["albumId"],
        }

        def fail_people_sql_album_item_assembly(row: dict[str, Any]) -> list[dict[str, Any]]:
            if str(row.get("albumId", "") or "") in sql_album_ids:
                raise AssertionError("persisted people smart albums should use SQL summaries/pages, not full album item assembly.")
            return original_album_items(row)

        def fail_python_assembly(*_args: Any, **_kwargs: Any) -> list[dict[str, Any]]:
            raise AssertionError("persisted people smart album pages should not assemble the full Photos library in Python.")

        api._photo_album_items = fail_people_sql_album_item_assembly
        try:
            folder = next(folder for folder in api.list_photo_folders({})["folders"] if folder.get("albumId") == album["albumId"])
            assert folder["coverSourcePath"] == alice, folder
            unknown_folder = next(folder for folder in api.list_photo_folders({})["folders"] if folder.get("albumId") == unknown_album["albumId"])
            assert unknown_folder["count"] == 1, unknown_folder
            unknown_dsl_folder = next(folder for folder in api.list_photo_folders({})["folders"] if folder.get("albumId") == unknown_dsl_album["albumId"])
            assert unknown_dsl_folder["count"] == 1, unknown_dsl_folder
            video_frames_folder = next(folder for folder in api.list_photo_folders({})["folders"] if folder.get("albumId") == video_frames_album["albumId"])
            assert video_frames_folder["count"] == 1, video_frames_folder
            video_frames_dsl_folder = next(folder for folder in api.list_photo_folders({})["folders"] if folder.get("albumId") == video_frames_dsl_album["albumId"])
            assert video_frames_dsl_folder["count"] == 1, video_frames_dsl_folder
        finally:
            api._photo_album_items = original_album_items

        api._all_photo_entries = fail_python_assembly
        api._photo_asset_entries = fail_python_assembly
        try:
            page = api.list_photo_folder_items({"folderId": f"album:{album['albumId']}", "previewBudget": 0})
            assert page["total"] == 1, page
            assert page["items"][0]["sourcePath"] == alice, page
            assert page["items"][0]["candidateIds"] == ["a1"], page
            assert all(item["sourcePath"] != together for item in page["items"]), page
            assert all(item["sourcePath"] != rejected for item in page["items"]), page
            memberships = page["items"][0]["albumMemberships"]
            assert any(item["name"] == "Alice without Bob" and item.get("derived") is True for item in memberships), memberships

            bob_page = api.list_photo_folder_items({"folderId": f"album:{bob_album['albumId']}", "sort": "filename", "previewBudget": 0})
            assert [item["sourcePath"] for item in bob_page["items"]] == [together, bob], bob_page
            pending_page = api.list_photo_folder_items({"folderId": f"album:{pending_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in pending_page["items"]] == [pending], pending_page
            unknown_page = api.list_photo_folder_items({"folderId": f"album:{unknown_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in unknown_page["items"]] == [unknown], unknown_page
            unknown_dsl_page = api.list_photo_folder_items({"folderId": f"album:{unknown_dsl_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in unknown_dsl_page["items"]] == [unknown], unknown_dsl_page
            video_frames_page = api.list_photo_folder_items({"folderId": f"album:{video_frames_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in video_frames_page["items"]] == [video], video_frames_page
            video_frames_dsl_page = api.list_photo_folder_items({"folderId": f"album:{video_frames_dsl_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in video_frames_dsl_page["items"]] == [video], video_frames_dsl_page
            dsl_page = api.list_photo_folder_items({"folderId": f"album:{dsl_album['albumId']}", "previewBudget": 0})
            assert [item["sourcePath"] for item in dsl_page["items"]] == [alice], dsl_page
            pending_all = api.list_photo_folder_items({"folderId": "all", "status": "pending", "sort": "filename", "previewBudget": 0})
            assert [item["sourcePath"] for item in pending_all["items"]] == [pending], pending_all
            quality_all = api.list_photo_folder_items({"folderId": "all", "minQuality": 0.91, "sort": "filename", "previewBudget": 0})
            assert [item["sourcePath"] for item in quality_all["items"]] == [pending], quality_all
            bob_all = api.list_photo_folder_items({"folderId": "all", "person": "Bob", "sort": "filename", "previewBudget": 0})
            assert [item["sourcePath"] for item in bob_all["items"]] == [together, bob], bob_all
            alice_pending_quality = api.list_photo_folder_items(
                {"folderId": "all", "person": "Alice", "status": "pending", "minQuality": 0.91, "sort": "filename", "previewBudget": 0}
            )
            assert [item["sourcePath"] for item in alice_pending_quality["items"]] == [pending], alice_pending_quality
            bob_pending = api.list_photo_folder_items({"folderId": "all", "person": "Bob", "status": "pending", "sort": "filename", "previewBudget": 0})
            assert bob_pending["items"] == [], bob_pending
        finally:
            api._all_photo_entries = original_all_entries
            api._photo_asset_entries = original_asset_entries
    print("ok smart album people rules read candidate-backed photo_assets without scan manifest")


