def test_photo_indexing_jobs_persist_and_run_local_ocr_queue() -> None:
    from PIL import Image

    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = base / "queued-ticket.png"
        Image.new("RGB", (80, 40), (255, 255, 255)).save(photo)
        photo.with_suffix(".txt").write_text("Queued boarding pass zone B", encoding="utf-8")
        photo_path = str(photo.resolve())
        api.import_photos({"sourcePaths": [photo_path], "storageMode": "referenced", "sourceLabel": "Queued OCR"})
        api.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": True,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": True,
                "indexingPowerMode": "low",
            }
        })

        queued = api.enqueue_photo_indexing_job({
            "jobKind": "ocr",
            "scope": {
                "sourcePaths": [photo_path, photo_path],
                "sidecarOnly": True,
                "language": "eng",
                "unsafePayload": "drop me",
            },
        })
        job = queued["job"]
        job_id = job["jobId"]
        assert queued["queued"] == 1, queued
        assert job["status"] == "queued", job
        assert job["jobKind"] == "ocr", job
        assert job["scope"]["sourcePaths"] == [photo_path], job
        assert "unsafePayload" not in job["scope"], job

        reopened = _api(tmp)
        persisted = reopened.photo_indexing_jobs({"limit": 5})
        assert persisted["queued"] == 1, persisted
        assert persisted["jobs"][0]["jobId"] == job_id, persisted

        paused = reopened.run_photo_indexing_job({"jobId": job_id})
        assert paused["job"]["status"] == "paused", paused
        assert paused["job"]["attempts"] == 1, paused
        assert paused["job"]["history"][-1]["status"] == "paused", paused
        assert paused["job"]["history"][-1]["attempt"] == 1, paused
        assert "paused" in paused["job"]["error"].lower(), paused
        paused_asset = reopened.project.db.photo_asset_by_path(photo_path)
        assert "ocrText" not in paused_asset["metadata"], paused_asset

        reopened.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": True,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": False,
                "indexingPowerMode": "low",
            }
        })
        completed = reopened.run_photo_indexing_job({"jobId": job_id})
        completed_job = completed["job"]
        assert completed_job["status"] == "completed", completed
        assert completed_job["attempts"] == 2, completed
        assert [entry["status"] for entry in completed_job["history"]] == ["paused", "completed"], completed
        assert completed_job["history"][-1]["attempt"] == 2, completed
        assert completed_job["result"]["progress"]["updated"] == 1, completed
        assert completed_job["history"][-1]["progress"]["updated"] == 1, completed
        assert completed["completed"] == 1, completed
        indexed_asset = reopened.project.db.photo_asset_by_path(photo_path)
        assert indexed_asset["metadata"]["ocrText"] == "Queued boarding pass zone B", indexed_asset
        search = reopened.search_photo_library({"query": "zone B"})
        photo_group = next(group for group in search["groups"] if group["id"] == "photos")
        assert photo_group["items"][0]["sourcePath"] == photo_path, photo_group

        batch_paths: list[str] = []
        for index, text in enumerate(("Batch queue orchid", "Batch queue invoice"), start=1):
            batch_photo = base / f"queued-batch-{index}.png"
            Image.new("RGB", (80, 40), (255, 255, 255)).save(batch_photo)
            batch_photo.with_suffix(".txt").write_text(text, encoding="utf-8")
            batch_path = str(batch_photo.resolve())
            batch_paths.append(batch_path)
            reopened.import_photos({"sourcePaths": [batch_path], "storageMode": "referenced", "sourceLabel": "Queued OCR batch"})
            enqueued = reopened.enqueue_photo_indexing_job({
                "jobKind": "ocr",
                "scope": {"sourcePaths": [batch_path], "sidecarOnly": True, "language": "eng"},
            })
            assert enqueued["queued"] >= 1, enqueued
        batch = reopened.run_photo_indexing_queue({"maxJobs": 2, "automatic": True})
        assert batch["ran"] == 2, batch
        assert batch["automatic"] is True, batch
        assert batch["progress"]["updated"] == 2, batch
        assert all(job["status"] == "completed" for job in batch["jobsRun"]), batch
        for batch_path in batch_paths:
            batch_asset = reopened.project.db.photo_asset_by_path(batch_path)
            assert "Batch queue" in batch_asset["metadata"]["ocrText"], batch_asset
        batch_search = reopened.search_photo_library({"query": "Batch queue"})
        batch_photo_group = next(group for group in batch_search["groups"] if group["id"] == "photos")
        assert {item["sourcePath"] for item in batch_photo_group["items"]} >= set(batch_paths), batch_photo_group

        pending_batch_paths: list[str] = []
        for index, text in enumerate(("Pending queue first", "Pending queue second"), start=1):
            pending_photo = base / f"queued-pending-{index}.png"
            Image.new("RGB", (80, 40), (255, 255, 255)).save(pending_photo)
            pending_photo.with_suffix(".txt").write_text(text, encoding="utf-8")
            pending_path = str(pending_photo.resolve())
            pending_batch_paths.append(pending_path)
            reopened.import_photos({"sourcePaths": [pending_path], "storageMode": "referenced", "sourceLabel": "Queued OCR pending batch"})
        pending_job_payload = reopened.enqueue_photo_indexing_job({
            "jobKind": "ocr",
            "scope": {"pendingOnly": True, "sidecarOnly": True, "language": "eng", "budgetLimit": 1},
        })
        pending_job_id = pending_job_payload["job"]["jobId"]
        pending_first = reopened.run_photo_indexing_queue({"maxJobs": 1})
        assert pending_first["ran"] == 1, pending_first
        assert pending_first["jobsRun"][0]["jobId"] == pending_job_id, pending_first
        assert pending_first["jobsRun"][0]["status"] == "queued", pending_first
        assert pending_first["jobsRun"][0]["result"]["pending"] is True, pending_first
        assert pending_first["jobsRun"][0]["result"]["progress"]["updated"] == 1, pending_first
        assert pending_first["jobsRun"][0]["result"]["progress"]["deferred"] == 1, pending_first
        pending_second = reopened.run_photo_indexing_queue({"maxJobs": 1})
        assert pending_second["ran"] == 1, pending_second
        assert pending_second["jobsRun"][0]["jobId"] == pending_job_id, pending_second
        assert pending_second["jobsRun"][0]["status"] == "completed", pending_second
        assert pending_second["jobsRun"][0]["result"]["pending"] is False, pending_second
        assert pending_second["jobsRun"][0]["result"]["progress"]["updated"] == 1, pending_second
        for pending_path in pending_batch_paths:
            pending_asset = reopened.project.db.photo_asset_by_path(pending_path)
            assert "Pending queue" in pending_asset["metadata"]["ocrText"], pending_asset

        empty = reopened.run_photo_indexing_queue({})
        assert empty["ran"] == 0, empty
        assert empty["stoppedReason"] == "empty", empty

        retry_photo = base / "queued-retry.png"
        Image.new("RGB", (80, 40), (255, 255, 255)).save(retry_photo)
        retry_photo.with_suffix(".txt").write_text("Retry failed queue payload", encoding="utf-8")
        retry_path = str(retry_photo.resolve())
        reopened.import_photos({"sourcePaths": [retry_path], "storageMode": "referenced", "sourceLabel": "Queued OCR retry"})
        retry_job_payload = reopened.enqueue_photo_indexing_job({
            "jobKind": "ocr",
            "scope": {"sourcePaths": [retry_path], "sidecarOnly": True, "language": "eng"},
        })
        retry_job_id = retry_job_payload["job"]["jobId"]
        reopened.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": False,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": False,
                "indexingPowerMode": "low",
            }
        })
        disabled_run = reopened.run_photo_indexing_job({"jobId": retry_job_id})
        assert disabled_run["job"]["status"] == "failed", disabled_run
        assert disabled_run["job"]["attempts"] == 1, disabled_run
        assert disabled_run["job"]["history"][-1]["status"] == "failed", disabled_run
        assert disabled_run["job"]["error"] == "Local intelligence is disabled in Photos settings.", disabled_run
        reopened.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": True,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": False,
                "indexingPowerMode": "low",
            }
        })
        skipped_failed = reopened.run_photo_indexing_queue({})
        assert skipped_failed["ran"] == 0, skipped_failed
        assert skipped_failed["failed"] == 1, skipped_failed
        retried_failed = reopened.run_photo_indexing_queue({"includeFailed": True})
        assert retried_failed["includeFailed"] is True, retried_failed
        assert retried_failed["ran"] == 1, retried_failed
        assert retried_failed["jobsRun"][0]["jobId"] == retry_job_id, retried_failed
        assert retried_failed["jobsRun"][0]["status"] == "completed", retried_failed
        assert retried_failed["jobsRun"][0]["attempts"] == 2, retried_failed
        assert [entry["status"] for entry in retried_failed["jobsRun"][0]["history"]] == ["failed", "completed"], retried_failed
        retry_asset = reopened.project.db.photo_asset_by_path(retry_path)
        assert retry_asset["metadata"]["ocrText"] == "Retry failed queue payload", retry_asset

        cancel_payload = reopened.enqueue_photo_indexing_job({
            "jobKind": "ocr",
            "scope": {"sourcePaths": [retry_path], "sidecarOnly": True, "force": True, "language": "eng"},
        })
        cancel_job_id = cancel_payload["job"]["jobId"]
        cancelled = reopened.cancel_photo_indexing_job({"jobId": cancel_job_id})
        assert cancelled["jobCancelled"] is True, cancelled
        assert cancelled["job"]["status"] == "cancelled", cancelled
        assert cancelled["job"]["attempts"] == 0, cancelled
        assert cancelled["job"]["history"][-1]["event"] == "cancelled", cancelled
        assert cancelled["cancelled"] == 1, cancelled
        cancelled_queue = reopened.run_photo_indexing_queue({})
        assert cancelled_queue["ran"] == 0, cancelled_queue
        dismissed = reopened.dismiss_photo_indexing_job({"jobId": cancel_job_id})
        assert dismissed["dismissed"] is True, dismissed
        assert dismissed["cancelled"] == 0, dismissed
    print("ok durable photo indexing queue persists and runs OCR jobs")


def test_photo_object_index_status_and_queue_materializes_metadata_tags() -> None:
    from PIL import Image

    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = base / "object-index-orchid.png"
        Image.new("RGB", (80, 40), (40, 80, 120)).save(photo)
        photo_path = str(photo.resolve())
        api.import_photos({"sourcePaths": [photo_path], "storageMode": "referenced", "sourceLabel": "Object index"})
        asset = api.project.db.photo_asset_by_path(photo_path)
        api.project.db.update_photo_asset_metadata_json(
            asset_id=asset["assetId"],
            patch={
                "objectTags": [{"label": "ceramic vase", "confidence": 0.94}],
                "sceneTags": ["sunlit kitchen"],
                "detectedEvents": {"birthday dinner": 0.88},
            },
        )
        with api.project.db.connect() as conn:
            conn.execute("DELETE FROM photo_object_tags WHERE asset_id = ?", (asset["assetId"],))
            api.project.db._index_photo_asset(asset["assetId"], conn)
        assert api.project.db.photo_object_tags_for_asset(asset["assetId"]) == []
        pending_status = api.photo_object_index_status({})
        assert pending_status["pending"] == 1, pending_status

        api.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": True,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": True,
                "indexingPowerMode": "low",
            }
        })
        queued = api.enqueue_photo_indexing_job({
            "jobKind": "object-tags",
            "scope": {"sourcePaths": [photo_path, photo_path], "unsafePayload": "drop me"},
        })
        job = queued["job"]
        job_id = job["jobId"]
        assert job["jobKind"] == "objects", job
        assert job["scope"]["sourcePaths"] == [photo_path], job
        assert "unsafePayload" not in job["scope"], job

        paused = api.run_photo_indexing_job({"jobId": job_id})
        assert paused["job"]["status"] == "paused", paused
        assert api.project.db.photo_object_tags_for_asset(asset["assetId"]) == []

        reopened = _api(tmp)
        reopened.save_photo_library_settings({
            "localSettings": {
                "localIntelligenceEnabled": True,
                "noNetworkIntelligence": True,
                "backgroundIndexingPaused": False,
                "indexingPowerMode": "low",
            }
        })
        completed = reopened.run_photo_indexing_job({"jobId": job_id})
        completed_job = completed["job"]
        assert completed_job["status"] == "completed", completed
        assert completed_job["attempts"] == 2, completed
        assert [entry["status"] for entry in completed_job["history"]] == ["paused", "completed"], completed
        assert completed_job["result"]["metadataOnly"] is True, completed
        assert completed_job["result"]["progress"]["updated"] == 1, completed
        indexed_asset = reopened.project.db.photo_asset_by_path(photo_path)
        indexed_rows = reopened.project.db.photo_object_tags_for_asset(indexed_asset["assetId"])
        indexed_labels = {(row["source"], row["label"]) for row in indexed_rows}
        assert ("object", "ceramic vase") in indexed_labels, indexed_rows
        assert ("scene", "sunlit kitchen") in indexed_labels, indexed_rows
        assert ("event", "birthday dinner") in indexed_labels, indexed_rows
        assert indexed_asset["metadata"]["localObjectTags"]["status"] == "indexed", indexed_asset
        assert indexed_asset["metadata"]["localObjectTags"]["tagCount"] == 3, indexed_asset
        search = reopened.search_photo_library({"query": "ceramic vase"})
        assert next(group for group in search["groups"] if group["id"] == "photos")["items"][0]["sourcePath"] == photo_path, search
        reviewed = reopened.update_photo_asset_metadata({
            "sourcePath": photo_path,
            "objectTagReview": {
                "entries": [
                    {"label": "ceramic vase", "source": "object", "action": "rejected", "reviewedAt": "2026-06-28T00:00:02Z"},
                    {"label": "silver spoon", "source": "user", "action": "confirmed", "confidence": 1.0, "reviewedAt": "2026-06-28T00:00:03Z"},
                ],
            },
        })
        assert reviewed["assetMetadata"]["objectTagReview"]["entries"][0]["action"] == "rejected", reviewed
        with reopened.project.db.connect() as conn:
            conn.execute("DELETE FROM photo_object_tags WHERE asset_id = ?", (indexed_asset["assetId"],))
            reopened.project.db._index_photo_asset(indexed_asset["assetId"], conn)
        reindexed = reopened.index_photo_objects({"sourcePaths": [photo_path], "force": True})
        assert reindexed["progress"]["updated"] == 1, reindexed
        reviewed_rows = reopened.project.db.photo_object_tags_for_asset(indexed_asset["assetId"])
        reviewed_labels = {(row["source"], row["label"]) for row in reviewed_rows}
        assert ("object", "ceramic vase") not in reviewed_labels, reviewed_rows
        assert ("user", "silver spoon") in reviewed_labels, reviewed_rows
        assert ("scene", "sunlit kitchen") in reviewed_labels, reviewed_rows
        assert reopened.list_photo_assets({"query": "ceramic vase", "backfill": True})["total"] == 0
        hidden_search = reopened.search_photo_library({"query": "ceramic vase"})
        assert not any("ceramic vase" in str(item.get("snippet", "")).casefold() for group in hidden_search["groups"] for item in group["items"]), hidden_search
        spoon_search = reopened.search_photo_library({"query": "silver spoon"})
        assert next(group for group in spoon_search["groups"] if group["id"] == "photos")["items"][0]["sourcePath"] == photo_path, spoon_search
        indexed_status = reopened.photo_object_index_status({})
        assert indexed_status["indexed"] == 1, indexed_status
        assert indexed_status["metadataOnly"] is True, indexed_status

        pending_paths: list[str] = []
        for index, label in enumerate(("queueable lantern", "queueable suitcase"), start=1):
            pending_photo = base / f"object-index-pending-{index}.png"
            Image.new("RGB", (80, 40), (80, 120, 40)).save(pending_photo)
            pending_path = str(pending_photo.resolve())
            pending_paths.append(pending_path)
            reopened.import_photos({"sourcePaths": [pending_path], "storageMode": "referenced", "sourceLabel": "Object pending"})
            pending_asset = reopened.project.db.photo_asset_by_path(pending_path)
            reopened.project.db.update_photo_asset_metadata_json(
                asset_id=pending_asset["assetId"],
                patch={"objectTags": [{"label": label, "confidence": 0.9}]},
            )
            with reopened.project.db.connect() as conn:
                conn.execute("DELETE FROM photo_object_tags WHERE asset_id = ?", (pending_asset["assetId"],))
                reopened.project.db._index_photo_asset(pending_asset["assetId"], conn)
        pending_job = reopened.enqueue_photo_indexing_job({
            "jobKind": "objects",
            "scope": {"pendingOnly": True, "budgetLimit": 1},
        })["job"]
        first = reopened.run_photo_indexing_queue({"maxJobs": 1})
        assert first["jobsRun"][0]["jobId"] == pending_job["jobId"], first
        assert first["jobsRun"][0]["status"] == "queued", first
        assert first["jobsRun"][0]["result"]["pending"] is True, first
        assert first["jobsRun"][0]["result"]["progress"]["updated"] == 1, first
        assert first["jobsRun"][0]["result"]["progress"]["deferred"] == 1, first
        second = reopened.run_photo_indexing_queue({"maxJobs": 1})
        assert second["jobsRun"][0]["jobId"] == pending_job["jobId"], second
        assert second["jobsRun"][0]["status"] == "completed", second
        for pending_path in pending_paths:
            row_asset = reopened.project.db.photo_asset_by_path(pending_path)
            assert reopened.project.db.photo_object_tags_for_asset(row_asset["assetId"]), pending_path

        empty_photo = base / "object-index-empty.png"
        Image.new("RGB", (80, 40), (120, 40, 80)).save(empty_photo)
        empty_path = str(empty_photo.resolve())
        reopened.import_photos({"sourcePaths": [empty_path], "storageMode": "referenced", "sourceLabel": "Object empty"})
        empty_result = reopened.index_photo_objects({"sourcePaths": [empty_path], "force": True})
        assert empty_result["progress"]["failed"] == 1, empty_result
        empty_status = reopened.photo_object_index_status({})
        assert any(row["status"] == "no_objects" and row["sourcePath"] == empty_path for row in empty_status["failures"]), empty_status
        retry_result = reopened.index_photo_objects({"failedOnly": True, "force": True})
        assert retry_result["progress"]["failed"] >= 1, retry_result
    print("ok photo object indexing materializes metadata tags through durable queue")


def test_photo_index_status_uses_sql_counts_without_full_asset_hydration() -> None:
    from PIL import Image

    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        ocr_photo = base / "status-ocr.png"
        barcode_photo = base / "status-barcode.png"
        object_photo = base / "status-object.png"
        pending_photo = base / "status-pending.png"
        for path in (ocr_photo, barcode_photo, object_photo, pending_photo):
            Image.new("RGB", (72, 40), (220, 220, 220)).save(path)
        imported = api.import_photos({
            "sourcePaths": [str(ocr_photo), str(barcode_photo), str(object_photo), str(pending_photo)],
            "storageMode": "referenced",
            "sourceLabel": "Index status SQL",
        })
        imported_by_name = {Path(path).name: path for path in imported["importedPaths"]}
        ocr_path = imported_by_name["status-ocr.png"]
        barcode_path = imported_by_name["status-barcode.png"]
        object_path = imported_by_name["status-object.png"]
        ocr_asset = api.project.db.photo_asset_by_path(ocr_path)
        barcode_asset = api.project.db.photo_asset_by_path(barcode_path)
        object_asset = api.project.db.photo_asset_by_path(object_path)
        assert ocr_asset and barcode_asset and object_asset
        api.project.db.replace_photo_ocr_blocks(
            ocr_asset["assetId"],
            [{"text": "schema OCR", "language": "eng", "confidence": 0.9, "bounds": {"x": 0, "y": 0, "width": 100, "height": 100}}],
        )
        api.project.db.update_photo_asset_metadata_json(
            asset_id=barcode_asset["assetId"],
            patch={"localBarcode": {"status": "no_code", "error": "No barcode"}, "barcodeText": ""},
        )
        api.project.db.update_photo_asset_metadata_json(
            asset_id=object_asset["assetId"],
            patch={"localObjectTags": {"status": "failed", "error": "Object metadata unavailable"}},
        )

        def fail_full_asset_loader(*_args: Any, **_kwargs: Any):
            raise AssertionError("status commands should use SQL counts, not full asset hydration")

        api._photo_ocr_all_assets = fail_full_asset_loader  # type: ignore[method-assign]

        ocr_status = api.photo_ocr_index_status({})
        barcode_status = api.photo_barcode_index_status({})
        object_status = api.photo_object_index_status({})

        assert ocr_status["total"] == 4, ocr_status
        assert ocr_status["indexed"] == 1, ocr_status
        assert ocr_status["pending"] == 3, ocr_status
        assert ocr_status["statusCounts"]["indexed"] == 1, ocr_status
        assert ocr_status["statusCounts"]["pending"] == 3, ocr_status

        assert barcode_status["total"] == 4, barcode_status
        assert barcode_status["pending"] == 3, barcode_status
        assert barcode_status["statusCounts"]["no_code"] == 1, barcode_status
        assert any(row["sourcePath"] == barcode_path and row["status"] == "no_code" for row in barcode_status["failures"]), barcode_status

        assert object_status["total"] == 4, object_status
        assert object_status["pending"] == 3, object_status
        assert object_status["statusCounts"]["failed"] == 1, object_status
        assert any(row["sourcePath"] == object_path and row["status"] == "failed" for row in object_status["failures"]), object_status
    print("ok photo index status uses SQL counts without full asset hydration")


def test_photo_operation_journal_orders_same_timestamp_by_insert_order() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        timestamp = "2026-06-28T00:00:00Z"
        empty_json = json.dumps({}, separators=(",", ":"))
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_operation_journal(
                    operation_id, operation_type, label, payload_json, undo_payload_json,
                    affected_count, created_at, undone_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, '')
                """,
                ("zz_older", "older", "Older operation", empty_json, empty_json, 1, timestamp),
            )
            conn.execute(
                """
                INSERT INTO photo_operation_journal(
                    operation_id, operation_type, label, payload_json, undo_payload_json,
                    affected_count, created_at, undone_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, '')
                """,
                ("aa_newer", "newer", "Newer operation", empty_json, empty_json, 1, timestamp),
            )

        operations = api.list_photo_operations({"limit": 2})["operations"]
        assert [operation["operationId"] for operation in operations] == ["aa_newer", "zz_older"], operations
        undone = api.undo_photo_operation({"operationId": ""})
        assert undone["undone"] is True, undone
        assert undone["operation"]["operationId"] == "aa_newer", undone
    print("ok photo operation journal orders same-timestamp rows by insertion order")


def test_photo_operation_journal_prunes_bounded_history() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        empty_json = json.dumps({"kind": "metadata", "items": [{"snapshot": "x" * 1024}]}, separators=(",", ":"))

        def insert_operation(conn: sqlite3.Connection, operation_id: str, created_at: str, undone_at: str = "") -> None:
            conn.execute(
                """
                INSERT INTO photo_operation_journal(
                    operation_id, operation_type, label, payload_json, undo_payload_json,
                    affected_count, created_at, undone_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (operation_id, "test", operation_id, empty_json, empty_json, 1, created_at, undone_at),
            )

        with api.project.db.connect() as conn:
            for index in range(5):
                insert_operation(conn, f"pending_{index}", f"2026-06-28T00:0{index}:00Z")
            for index in range(4):
                insert_operation(conn, f"undone_{index}", f"2026-06-27T00:0{index}:00Z", f"2026-06-29T00:0{index}:00Z")
            deleted = api.project.db.prune_photo_operation_journal(pending_limit=2, undone_limit=1, conn=conn)
            rows = conn.execute(
                """
                SELECT operation_id, undone_at
                FROM photo_operation_journal
                ORDER BY undone_at = '' DESC, created_at DESC, rowid DESC
                """
            ).fetchall()

        assert deleted == {"pendingDeleted": 3, "undoneDeleted": 3}, deleted
        pending = [str(row["operation_id"]) for row in rows if str(row["undone_at"] or "") == ""]
        undone = [str(row["operation_id"]) for row in rows if str(row["undone_at"] or "") != ""]
        assert pending == ["pending_4", "pending_3"], rows
        assert undone == ["undone_3"], rows
    print("ok photo operation journal prunes bounded pending and undone history")


def test_photo_operation_journal_auto_prunes_after_record() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        empty_json = json.dumps({"kind": "metadata", "items": [{"snapshot": "x" * 512}]}, separators=(",", ":"))
        pending_limit = workspace_db_module.PHOTO_OPERATION_JOURNAL_PENDING_LIMIT
        undone_limit = workspace_db_module.PHOTO_OPERATION_JOURNAL_UNDONE_LIMIT

        with api.project.db.connect() as conn:
            for index in range(pending_limit + 5):
                conn.execute(
                    """
                    INSERT INTO photo_operation_journal(
                        operation_id, operation_type, label, payload_json, undo_payload_json,
                        affected_count, created_at, undone_at
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, '')
                    """,
                    (f"pending_old_{index:03d}", "test", "old pending", empty_json, empty_json, 1, f"2026-06-27T00:{index % 60:02d}:00Z"),
                )
            for index in range(undone_limit + 4):
                conn.execute(
                    """
                    INSERT INTO photo_operation_journal(
                        operation_id, operation_type, label, payload_json, undo_payload_json,
                        affected_count, created_at, undone_at
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        f"undone_old_{index:03d}",
                        "test",
                        "old undone",
                        empty_json,
                        empty_json,
                        1,
                        f"2026-06-26T00:{index % 60:02d}:00Z",
                        f"2026-06-28T00:{index % 60:02d}:00Z",
                    ),
                )
            operation = api.project.db.record_photo_album_items_operation(
                operation_type="test_album_op",
                label="Newest album operation",
                album_id="album-prune",
                previous={"items": []},
                affected_count=1,
                created_at="2026-06-30T00:00:00Z",
                conn=conn,
            )
            pending_count = int(conn.execute("SELECT COUNT(*) AS n FROM photo_operation_journal WHERE undone_at = ''").fetchone()["n"])
            undone_count = int(conn.execute("SELECT COUNT(*) AS n FROM photo_operation_journal WHERE undone_at != ''").fetchone()["n"])
            newest = api.project.db.list_photo_operations(limit=1, conn=conn)[0]

        assert operation["operationId"], operation
        assert pending_count == pending_limit, pending_count
        assert undone_count == undone_limit, undone_count
        assert newest["operationId"] == operation["operationId"], newest
    print("ok photo operation journal auto-prunes after recording operations")


def test_photo_review_decision_records_operation_and_undo() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = str(base / "decision-ada.jpg")
        Path(photo).write_bytes(b"decision photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        api.project.db.record_scan_file("run1", Path(photo), _sig(Path(photo)), "completed", phase="processed")
        api.project.candidates = {
            "decision": _candidate("decision", "Ada", photo, status="pending", score=0.82, quality=0.91),
        }
        api.project.db.upsert_candidates(api.project.candidates.values())

        api.handle("set_status", {"candidateId": "decision", "status": "accepted"})
        operations = api.list_photo_operations({"limit": 3, "includeUndone": True})["operations"]
        operation = operations[0]
        assert operation["operationType"] == "review_candidate_decision", operation
        assert operation["label"] == "Marked Ada review as Accepted", operation
        payload = operation["payload"]
        assert payload["personName"] == "Ada", payload
        assert payload["sourceFilename"] == "decision-ada.jpg", payload
        assert payload["statusBefore"] == "pending", payload
        assert payload["statusAfter"] == "accepted", payload
        assert payload["scoreBefore"] == 0.82, payload
        assert payload["qualityBefore"] == 0.91, payload
        assert payload["labelId"], payload
        assert payload["trainingExampleId"], payload
        people = api.project.db.list_photo_asset_people(api.project.db.photo_asset_by_path(photo)["assetId"])
        assert people and people[0]["status"] == "accepted", people

        undone = api.undo_photo_operation({"operationId": operation["operationId"]})
        assert undone["undone"] is True, undone
        assert undone["restored"] >= 1, undone
        assert api.project.candidates["decision"].status == "pending"
        restored_people = api.project.db.list_photo_asset_people(api.project.db.photo_asset_by_path(photo)["assetId"])
        assert restored_people and restored_people[0]["status"] == "pending", restored_people
        api.project.load()
        assert api.project.candidates["decision"].status == "pending"
    print("ok photo review decision records operation and undo")


def test_photo_operation_journal_undoes_metadata_edits() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = str(base / "metadata.jpg")
        Path(photo).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        api.project.db.record_scan_file("run1", Path(photo), _sig(Path(photo)), "completed", phase="processed")
        asset = api.project.db.photo_asset_by_path(photo)
        assert asset is not None
        with api.project.db.connect() as conn:
            conn.execute(
                "UPDATE photo_assets SET capture_date = ? WHERE asset_id = ?",
                ("2026-05-31T23:00:00Z", asset["assetId"]),
            )
            api.project.db._index_photo_asset(str(asset["assetId"]), conn)
        api.project.db.update_photo_asset_metadata(
            source_path=photo,
            title="Original title",
            caption="Original caption",
            favorite=False,
            date_override="2026-06-01",
            location_override={"label": "Original place", "latitude": "1", "longitude": "2"},
            location_hidden=False,
            edited=False,
            keywords=["original"],
        )
        api.project.db.update_photo_asset_metadata_json(
            source_path=photo,
            patch={
                "accessibilityDescription": "Original accessible note",
                "localDepthControls": {"mode": "portrait", "modeLabel": "Portrait", "aperture": "4", "focusDistance": "2", "effect": "Natural Light"},
                "descriptionRegions": [
                    {"id": "original-region", "text": "Original region note", "x": 1, "y": 2, "width": 30, "height": 20},
                ],
            },
        )

        updated = api.update_photo_asset_metadata(
            {
                "sourcePath": photo,
                "title": "Edited title",
                "caption": "Edited caption",
                "accessibilityDescription": "Edited accessible note",
                "descriptionRegions": [
                    {"id": "edited-region", "text": "Edited region note", "x": 10, "y": 20, "width": 30, "height": 40},
                ],
                "favorite": True,
                "captureDate": "2026-06-01T23:00:00Z",
                "dateOverride": "2026-06-02T03:04:05+05:30",
                "locationOverride": {"label": "Edited place", "latitude": "3", "longitude": "4"},
                "locationHidden": True,
                "localDepthControls": {"modeLabel": "Cinematic", "fNumber": "1.4", "subjectDistance": "0.6", "portraitEffect": "Stage Light"},
                "keywords": ["edited", "original"],
            }
        )
        assert updated["operation"]["operationType"] == "metadata_update", updated
        assert updated["operation"]["canUndo"] is True, updated
        assert updated["title"] == "Edited title", updated
        assert updated["accessibilityDescription"] == "Edited accessible note", updated
        assert updated["descriptionRegions"][0]["text"] == "Edited region note", updated
        assert updated["favorite"] is True, updated
        assert updated["captureDate"] == "2026-06-01T23:00:00Z", updated
        assert updated["assetMetadata"]["localDepthControls"] == {
            "mode": "cinematic",
            "modeLabel": "Cinematic",
            "aperture": "1.4",
            "focusDistance": "0.6",
            "effect": "Stage Light",
        }, updated
        assert set(updated["keywords"]) == {"edited", "original"}, updated
        operations = api.list_photo_operations({"limit": 1})["operations"]
        assert operations and operations[0]["operationId"] == updated["operation"]["operationId"], operations

        undo = api.undo_photo_operation({"operationId": updated["operation"]["operationId"]})
        assert undo["undone"] is True, undo
        assert undo["restored"] == 1, undo
        restored = api.project.db.photo_asset_metadata_by_path(photo)
        assert restored["title"] == "Original title", restored
        assert restored["caption"] == "Original caption", restored
        assert restored["accessibilityDescription"] == "Original accessible note", restored
        assert restored["descriptionRegions"][0]["text"] == "Original region note", restored
        assert restored["localDepthControls"]["effect"] == "Natural Light", restored
        assert restored["localDepthControls"]["modeLabel"] == "Portrait", restored
        assert restored["favorite"] is False, restored
        assert restored["dateOverride"] == "2026-06-01", restored
        assert restored["locationOverride"]["label"] == "Original place", restored
        assert restored["locationHidden"] is False, restored
        assert restored["edited"] is False, restored
        assert restored["keywords"] == ["original"], restored
        restored_asset = api.project.db.photo_asset_by_path(photo)
        assert restored_asset and restored_asset["captureDate"] == "2026-05-31T23:00:00Z", restored_asset
        assert api.list_photo_operations({"limit": 1})["operations"] == []
    print("ok photo operation journal undo metadata edits")


def test_photo_operation_journal_groups_bulk_metadata_edits() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        first = str(base / "first.jpg")
        second = str(base / "second.jpg")
        for path in (first, second):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        api.project.db.record_scan_file("run1", Path(first), _sig(Path(first)), "completed", phase="processed")
        api.project.db.record_scan_file("run1", Path(second), _sig(Path(second)), "completed", phase="processed")
        api.project.db.update_photo_asset_metadata(source_path=first, date_override="2026-06-01", keywords=["old"], edited=False)
        api.project.db.update_photo_asset_metadata(source_path=second, date_override="2026-06-02", keywords=["old"], edited=False)

        result = api.update_photo_assets_metadata(
            {
                "label": "Offset selected dates",
                "items": [
                    {"sourcePath": first, "dateOverride": "2026-06-11", "keywords": ["new", "first"]},
                    {"sourcePath": second, "dateOverride": "2026-06-12", "keywords": ["new", "second"]},
                ],
            }
        )
        assert result["updated"] == 2, result
        assert result["changed"] == 2, result
        assert result["operation"]["operationType"] == "metadata_update", result
        assert result["operation"]["affectedCount"] == 2, result
        assert result["operation"]["label"] == "Offset selected dates", result
        operations = api.list_photo_operations({"limit": 1})["operations"]
        assert operations and operations[0]["operationId"] == result["operation"]["operationId"], operations

        undo = api.undo_photo_operation({"operationId": result["operation"]["operationId"]})
        assert undo["undone"] is True, undo
        assert undo["restored"] == 2, undo
        first_metadata = api.project.db.photo_asset_metadata_by_path(first)
        second_metadata = api.project.db.photo_asset_metadata_by_path(second)
        assert first_metadata["dateOverride"] == "2026-06-01", first_metadata
        assert second_metadata["dateOverride"] == "2026-06-02", second_metadata
        assert first_metadata["keywords"] == ["old"], first_metadata
        assert second_metadata["keywords"] == ["old"], second_metadata
        assert first_metadata["edited"] is False, first_metadata
        assert second_metadata["edited"] is False, second_metadata
    print("ok photo operation journal groups bulk metadata edits")


