def test_photo_library_search_categorizes_local_results() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        harbor_folder = base / "Harbor Sources"
        harbor_folder.mkdir()
        harbor = str(harbor_folder / "harbor.jpg")
        harbor_neutral = str(harbor_folder / "harbor-neutral.jpg")
        portrait = str(base / "portrait.jpg")
        receipt = str(base / "expense.jpg")
        hidden = str(harbor_folder / "hidden-harbor.jpg")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (harbor, harbor_neutral, portrait, receipt, hidden):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.candidates = {
            "c1": _candidate("c1", "Harbor Guest", harbor, status="accepted", capture_date="2026-06-19"),
        }
        api.update_photo_asset_metadata(
            {
                "sourcePath": harbor,
                "title": "Harbor picnic",
                "caption": "Blue hour by the boats",
                "dateOverride": "2026-06-19",
                "locationOverride": {"label": "Harbor Point", "latitude": "36.9741", "longitude": "-122.0308"},
                "keywords": ["harbor", "travel"],
            }
        )
        api.update_photo_asset_metadata({"sourcePath": portrait, "title": "Studio portrait", "dateOverride": "2025-01-02"})
        portrait_asset = api.project.db.photo_asset_by_path(portrait)
        assert portrait_asset is not None, portrait_asset
        api.project.db.update_photo_asset_metadata_json(
            asset_id=portrait_asset["assetId"],
            patch={
                "exif": {"cameraModel": "SearchCam 1000", "lensModel": "Prime Lens"},
                "ocrText": "Boarding pass ticket number ZX-42",
                "objectTags": [{"label": "red suitcase", "confidence": 0.92}],
                "modelTags": [{"label": "travel gear", "confidence": 0.94}],
                "colorProfile": "Dolby Vision HDR",
                "deviceModel": "iPhone 15 Pro",
                "video": {"codecName": "HEVC"},
                "probe": {"format": "QuickTime"},
                "cinematicMode": "Cinematic focus",
                "depthMap": {"label": "Depth map available"},
            },
        )
        receipt_asset = api.project.db.photo_asset_by_path(receipt)
        assert receipt_asset is not None, receipt_asset
        api.update_photo_asset_metadata({"sourcePath": receipt, "title": "Cafe image", "dateOverride": "2026-06-21"})
        api.project.db.update_photo_asset_metadata_json(
            asset_id=receipt_asset["assetId"],
            patch={"ocrText": "Cafe Receipt Total $18.50"},
        )
        api.update_photo_asset_metadata({"sourcePath": hidden, "title": "Secret Harbor", "hidden": True})
        album = api.save_photo_album({"name": "Harbor album", "albumKind": "manual"})
        api.add_photo_album_items({"albumId": album["albumId"], "sourcePaths": [harbor]})

        result = api.search_photo_library({"query": "Harbor", "limit": 4})
        groups = {group["id"]: group for group in result["groups"]}
        assert {"photos", "albums", "people", "places", "keywords", "sourceFolders"} <= set(groups), result
        assert groups["photos"]["items"][0]["sourcePath"] == harbor, groups["photos"]
        assert groups["albums"]["items"][0]["folderId"] == f"album:{album['albumId']}", groups["albums"]
        assert groups["people"]["items"][0]["folderId"] == "person:Harbor Guest", groups["people"]
