        api.update_photo_asset_metadata({"sourcePath": old_deleted, "deletedAt": "2026-01-01T00:00:00Z"})
        api.update_photo_asset_metadata({"sourcePath": recent_deleted, "deletedAt": "2026-06-01T00:00:00Z"})

