def test_photo_operation_journal_undoes_recoverable_permanent_delete() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        photo = str(base / "recoverable-delete.jpg")
        Path(photo).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        api.project.db.record_scan_file("run1", Path(photo), _sig(Path(photo)), "completed", phase="processed")
        api.update_photo_asset_metadata(
            {
                "sourcePath": photo,
                "title": "Recoverable",
                "keywords": ["archive"],
                "deletedAt": "2026-06-20T00:00:00Z",
            }
        )
        album = api.save_photo_album({"name": "Deleted picks", "albumKind": "manual"})
        api.add_photo_album_items({"albumId": album["albumId"], "sourcePaths": [photo]})
        asset = api.project.db.photo_asset_by_path(photo)
        assert asset, asset
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, 'accepted', 0.99, 0.95, 'manual assignment', '2026-06-20T00:00:00Z')
                """,
                (asset["assetId"], "manual-alice", "Alice"),
            )

        permanent = api.permanently_delete_photos({"sourcePaths": [photo]})
        assert permanent["deletedAssets"] == 1, permanent
        assert permanent["operation"]["operationType"] == "catalog_permanent_delete", permanent
        assert permanent["operation"]["canUndo"] is True, permanent
        assert Path(photo).exists(), permanent
        assert api.project.db.photo_asset_by_path(photo) is None
        with api.project.db.connect() as conn:
            scan_count = int(conn.execute("SELECT COUNT(*) AS n FROM scan_files WHERE path = ?", (photo,)).fetchone()["n"])
            assert scan_count == 0, permanent

        undo = api.undo_photo_operation({"operationId": permanent["operation"]["operationId"]})
        assert undo["undone"] is True, undo
        assert undo["restored"] == 1, undo
        restored = api.project.db.photo_asset_by_path(photo)
        assert restored and restored["assetId"] == asset["assetId"], restored
        metadata = api.project.db.photo_asset_metadata_by_path(photo)
        assert metadata["title"] == "Recoverable", metadata
        assert metadata["deletedAt"] == "2026-06-20T00:00:00Z", metadata
        assert metadata["keywords"] == ["archive"], metadata
        with api.project.db.connect() as conn:
            membership_count = int(
                conn.execute(
                    "SELECT COUNT(*) AS n FROM photo_album_items WHERE album_id = ? AND asset_id = ?",
                    (album["albumId"], asset["assetId"]),
                ).fetchone()["n"]
            )
            assert membership_count == 1, undo
        people = api.project.db.list_photo_asset_people(asset["assetId"])
        assert people and people[0]["personName"] == "Alice", people
        with api.project.db.connect() as conn:
            scan_count = int(conn.execute("SELECT COUNT(*) AS n FROM scan_files WHERE path = ?", (photo,)).fetchone()["n"])
            assert scan_count == 1, undo
        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["recentlyDeleted"]["count"] == 1, folders
    print("ok photo operation journal undo recoverable permanent delete")


def test_photo_permanent_delete_trashes_managed_original_and_undo_restores() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        source = base / "managed-source.jpg"
        source.write_bytes(b"managed original bytes")
        managed_root = base / "managed-root"
        imported = api.import_photos(
            {
                "sourcePaths": [str(source)],
                "storageMode": "managed",
                "managedRoot": str(managed_root),
                "sourceLabel": "Managed delete import",
            }
        )
        managed_path = Path(imported["importedPaths"][0])
        assert managed_path.exists(), imported
        assert managed_path.read_bytes() == b"managed original bytes"
        api.update_photo_asset_metadata({"sourcePath": str(managed_path), "deletedAt": "2026-06-20T00:00:00Z"})

        permanent = api.permanently_delete_photos({"sourcePaths": [str(managed_path)]})
        assert permanent["deletedAssets"] == 1, permanent
        assert permanent["deletedFiles"] == 1, permanent
        assert permanent["managedOriginalsTrashed"] == 1, permanent
        assert permanent["originalMediaDeleted"] is True, permanent
        trash_paths = [Path(path) for path in permanent["managedOriginalTrashPaths"]]
        assert len(trash_paths) == 1, permanent
        assert trash_paths[0].exists(), permanent
        assert trash_paths[0].read_bytes() == b"managed original bytes"
        assert "managed-trash" in str(trash_paths[0]), permanent
        assert not managed_path.exists(), permanent
        assert source.exists(), permanent
        assert api.project.db.photo_asset_by_path(str(managed_path)) is None

        undo = api.undo_photo_operation({"operationId": permanent["operation"]["operationId"]})
        assert undo["undone"] is True, undo
        assert undo["restored"] == 1, undo
        assert managed_path.exists(), undo
        assert managed_path.read_bytes() == b"managed original bytes"
        assert not trash_paths[0].exists(), undo
        restored = api.project.db.photo_asset_by_path(str(managed_path))
        assert restored and restored["sourceKind"] == "managed", restored
        metadata = api.project.db.photo_asset_metadata_by_path(str(managed_path))
        assert metadata["deletedAt"] == "2026-06-20T00:00:00Z", metadata
    print("ok managed permanent delete moves original to app trash and undo restores it")


def test_photo_restore_rehearsal_recovers_catalog_after_managed_trash_cleanup() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        source = base / "managed-cleanup-source.jpg"
        source.write_bytes(b"managed original bytes before cleanup")
        managed_root = base / "managed-root"
        imported = api.import_photos(
            {
                "sourcePaths": [str(source)],
                "storageMode": "managed",
                "managedRoot": str(managed_root),
                "sourceLabel": "Managed cleanup restore",
            }
        )
        managed_path = Path(imported["importedPaths"][0])
        api.update_photo_asset_metadata({"sourcePath": str(managed_path), "deletedAt": "2026-06-20T00:00:00Z"})
        permanent = api.permanently_delete_photos({"sourcePaths": [str(managed_path)]})
        operation_id = permanent["operation"]["operationId"]
        trash_path = Path(permanent["managedOriginalTrashPaths"][0])
        assert trash_path.exists(), permanent
        trash_path.unlink()

        rehearsal = api.photo_restore_rehearsal({"operationId": operation_id})
        assert rehearsal["ok"] is True, rehearsal
        assert rehearsal["status"] == "warning", rehearsal
        assert rehearsal["counts"]["operations"] == 1, rehearsal
        assert rehearsal["counts"]["missingManagedTrashItems"] == 1, rehearsal
        assert rehearsal["counts"]["missingOriginalItems"] == 1, rehearsal
        assert rehearsal["counts"]["blockedItems"] == 0, rehearsal
        issue = rehearsal["operations"][0]["items"][0]
        assert issue["issue"] == "managed_trash_missing", issue
        assert issue["canRestoreCatalog"] is True, issue
        assert issue["canRestoreOriginal"] is False, issue

        undo = api.undo_photo_operation({"operationId": operation_id})
        assert undo["undone"] is True, undo
        assert undo["restored"] == 1, undo
        assert undo["missing"] == 0, undo
        assert undo["missingOriginals"] == 1, undo
        assert not managed_path.exists(), undo
        restored = api.project.db.photo_asset_by_path(str(managed_path))
        assert restored and restored["sourceKind"] == "managed", restored
        assert restored["missingAt"], restored
        metadata = api.project.db.photo_asset_metadata_by_path(str(managed_path))
        assert metadata["deletedAt"] == "2026-06-20T00:00:00Z", metadata
    print("ok photo restore rehearsal recovers catalog after managed trash cleanup")


