def test_photo_richer_media_type_detection_and_folders() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        panorama = str(base / "Vacation PANO 001.jpg")
        portrait = str(base / "Portrait mode Ada.jpg")
        burst = str(base / "Birthday Burst 0001.jpg")
        time_lapse = str(base / "Desert Time Lapse.mov")
        raw = str(base / "Camera original.dng")
        live_photo = str(base / "Kitchen Live Photo.heic")
        paired_live_photo = str(base / "IMG_0100.HEIC")
        paired_motion = base / "IMG_0100.MOV"
        paired_motion.write_bytes(b"motion")
        api.project.db.create_scan_run("run-media", "label", "manual", str(base))
        for path in (panorama, portrait, burst, time_lapse, raw, live_photo, paired_live_photo):
            api.project.db.record_scan_file("run-media", Path(path), _sig(Path(path)), "completed", phase="processed")

        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["media:panorama"]["count"] == 1, folders
        assert folders["media:portrait"]["count"] == 1, folders
        assert folders["media:burst"]["count"] == 1, folders
        assert folders["media:time_lapse"]["count"] == 1, folders
        assert folders["media:raw"]["count"] == 1, folders
        assert folders["media:live_photo"]["count"] == 2, folders

        expected = {
            "panorama": panorama,
            "portrait": portrait,
            "burst": burst,
            "time_lapse": time_lapse,
            "raw": raw,
        }
        for media_kind, source_path in expected.items():
            page = api.list_photo_folder_items({"folderId": "all", "mediaKind": media_kind, "sort": "filename", "previewBudget": 0})
            assert [item["sourcePath"] for item in page["items"]] == [source_path], (media_kind, page)
            folder_page = api.list_photo_folder_items({"folderId": f"media:{media_kind}", "sort": "filename", "previewBudget": 0})
            assert [item["mediaKind"] for item in folder_page["items"]] == [media_kind], (media_kind, folder_page)

        live_page = api.list_photo_folder_items({"folderId": "all", "mediaKind": "live_photo", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in live_page["items"]] == [paired_live_photo, live_photo], live_page
        paired_asset = api.project.db.photo_asset_by_path(paired_live_photo)
        assert paired_asset and paired_asset["mediaKind"] == "live_photo", paired_asset
        assert Path(paired_asset["metadata"]["livePhoto"]["pairedVideoPath"]).samefile(paired_motion), paired_asset

        asset_page = api.list_photo_assets({"mediaKind": "time_lapse", "limit": 10})
        assert [item["sourcePath"] for item in asset_page["items"]] == [time_lapse], asset_page
    print("ok richer Photos media-type detection and folders")


def test_photo_burst_stacks_detect_and_keep_selection() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        burst_one = str(base / "Birthday Burst 0001.jpg")
        burst_two = str(base / "Birthday Burst 0002.jpg")
        burst_three = str(base / "Birthday Burst 0003 cover.jpg")
        other = str(base / "Birthday solo.jpg")
        api.project.db.create_scan_run("run-burst", "label", "manual", str(base))
        for path in (burst_one, burst_two, burst_three, other):
            api.project.db.record_scan_file("run-burst", Path(path), _sig(Path(path)), "completed", phase="processed")

        result = api.list_photo_burst_stacks({"includeItems": True})
        assert result["total"] == 1, result
        stack = result["stacks"][0]
        assert stack["count"] == 3, stack
        assert stack["coverSourcePath"] == burst_three, stack
        assert stack["sourcePaths"] == [burst_one, burst_two, burst_three], stack
        assert [item["sequence"] for item in stack["items"]] == [1, 2, 3], stack
        uncollapsed_page = api.list_photo_folder_items({"folderId": "media:burst", "sort": "filename", "previewBudget": 0})
        assert uncollapsed_page["total"] == 3, uncollapsed_page
        collapsed_page = api.list_photo_folder_items({"folderId": "media:burst", "sort": "filename", "previewBudget": 0, "collapseBursts": True})
        assert collapsed_page["total"] == 1, collapsed_page
        collapsed_item = collapsed_page["items"][0]
        assert collapsed_item["sourcePath"] == burst_three, collapsed_item
        assert collapsed_item["burstStack"]["stackId"] == stack["stackId"], collapsed_item
        assert collapsed_item["burstStack"]["count"] == 3, collapsed_item
        assert collapsed_item["burstStack"]["keeperCount"] == 0, collapsed_item
        assert collapsed_item["burstStack"]["sourcePaths"] == [burst_one, burst_two, burst_three], collapsed_item

        selected = api.set_photo_burst_selection({
            "stackId": stack["stackId"],
            "keepSourcePaths": [burst_two],
        })
        assert selected["selectedCount"] == 1, selected
        assert selected["updated"] == 3, selected
        selected_stack = selected["stack"]
        assert selected_stack["keeperCount"] == 1, selected_stack
        assert selected_stack["coverSourcePath"] == burst_two, selected_stack
        roles = {
            Path(item["sourcePath"]).name: item["selectionRole"]
            for item in selected_stack["items"]
        }
        assert roles["Birthday Burst 0002.jpg"] == "keeper", roles
        assert roles["Birthday Burst 0001.jpg"] == "alternate", roles
        selected_collapsed_page = api.list_photo_folder_items({"folderId": "media:burst", "sort": "filename", "previewBudget": 0, "collapseBursts": True})
        assert selected_collapsed_page["total"] == 1, selected_collapsed_page
        selected_collapsed_item = selected_collapsed_page["items"][0]
        assert selected_collapsed_item["sourcePath"] == burst_two, selected_collapsed_item
        assert selected_collapsed_item["burstStack"]["keeperCount"] == 1, selected_collapsed_item
        assert selected_collapsed_item["burstStack"]["representativeSourcePath"] == burst_two, selected_collapsed_item

        keeper_asset = api.project.db.photo_asset_by_path(burst_two)
        assert keeper_asset is not None, selected
        assert keeper_asset["metadata"]["burst"]["isKeeper"] is True, keeper_asset
        assert keeper_asset["metadata"]["burst"]["selectionRole"] == "keeper", keeper_asset

        _expect_raises(
            ValueError,
            lambda: api.set_photo_burst_selection({
                "stackId": stack["stackId"],
                "keepSourcePaths": [other],
            }),
            "belong",
        )

        cleared = api.set_photo_burst_selection({"sourcePath": burst_two, "clear": True})
        assert cleared["cleared"] is True, cleared
        assert cleared["stack"]["keeperCount"] == 0, cleared
        cleared_collapsed_page = api.list_photo_folder_items({"folderId": "media:burst", "sort": "filename", "previewBudget": 0, "collapseBursts": True})
        assert cleared_collapsed_page["items"][0]["sourcePath"] == burst_three, cleared_collapsed_page
        cleared_asset = api.project.db.photo_asset_by_path(burst_two)
        assert cleared_asset is not None, cleared
        assert "isKeeper" not in cleared_asset["metadata"]["burst"], cleared_asset
        assert "selectionRole" not in cleared_asset["metadata"]["burst"], cleared_asset
    print("ok photo burst stack detection and keep selection")


def test_photo_burst_stacks_avoid_full_asset_page() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        burst_one = str(base / "Fast Burst 0001.jpg")
        burst_two = str(base / "Fast Burst 0002 cover.jpg")
        regular = str(base / "regular-family-photo.jpg")
        api.project.db.create_scan_run("run-burst-fast", "label", "manual", str(base))
        for path in (burst_one, burst_two, regular):
            api.project.db.record_scan_file("run-burst-fast", Path(path), _sig(Path(path)), "completed", phase="processed")

        original_page = api.project.db.list_photo_asset_page
        original_candidates = api.project.db.list_photo_burst_candidate_assets
        candidate_calls = 0

        def fail_full_asset_page(*_args: Any, **_kwargs: Any) -> dict[str, Any]:
            raise AssertionError("burst stack operations must not page the full photo asset table")

        def counted_burst_candidates(*args: Any, **kwargs: Any) -> list[dict[str, Any]]:
            nonlocal candidate_calls
            if kwargs.get("conn") is None:
                candidate_calls += 1
            return original_candidates(*args, **kwargs)

        api.project.db.list_photo_asset_page = fail_full_asset_page  # type: ignore[method-assign]
        api.project.db.list_photo_burst_candidate_assets = counted_burst_candidates  # type: ignore[method-assign]
        try:
            result = api.list_photo_burst_stacks({"includeItems": True})
            assert result["total"] == 1, result
            assert result["stacks"][0]["sourcePaths"] == [burst_one, burst_two], result
            assert candidate_calls == 1, candidate_calls
            candidate_calls = 0
            selected = api.set_photo_burst_selection({"sourcePath": burst_one})
            assert selected["selectedCount"] == 1, selected
            assert selected["updated"] == 2, selected
            assert selected["stack"]["coverSourcePath"] == burst_one, selected
        finally:
            api.project.db.list_photo_asset_page = original_page  # type: ignore[method-assign]
            api.project.db.list_photo_burst_candidate_assets = original_candidates  # type: ignore[method-assign]
        assert candidate_calls <= 2, candidate_calls
    print("ok photo burst stack operations avoid full asset paging")


def test_photo_burst_stacks_detect_native_metadata_identifiers() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        frame_one = str(base / "IMG_5001.jpg")
        frame_two = str(base / "IMG_5002.jpg")
        frame_three = str(base / "IMG_5003.jpg")
        api.project.db.create_scan_run("run-native-burst", "label", "manual", str(base))
        for path in (frame_one, frame_two, frame_three):
            api.project.db.record_scan_file("run-native-burst", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.db.update_photo_asset_metadata_json(
            source_path=frame_one,
            patch={
                "exif": {
                    "BurstUUID": "APPLE-NATIVE-BURST-1",
                    "BurstSequence": 1,
                    "BurstSelectionTypes": ["autoPick"],
                },
                "burstName": "Native metadata burst",
            },
        )
        api.project.db.update_photo_asset_metadata_json(
            source_path=frame_two,
            patch={
                "image": {
                    "exif": {
                        "BurstIdentifier": "APPLE-NATIVE-BURST-1",
                        "BurstFrameIndex": 2,
                        "BurstSelectionTypes": ["userPick"],
                    },
                },
            },
        )
        api.project.db.update_photo_asset_metadata_json(
            source_path=frame_three,
            patch={
                "xmp": {
                    "photos": {
                        "burstIdentifier": "APPLE-NATIVE-BURST-1",
                        "burstSequence": 3,
                    },
                },
            },
        )

        for path in (frame_one, frame_two, frame_three):
            asset = api.project.db.photo_asset_by_path(path)
            assert asset and asset["mediaKind"] == "burst", asset

        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["media:burst"]["count"] == 3, folders["media:burst"]
        result = api.list_photo_burst_stacks({"includeItems": True})
        assert result["total"] == 1, result
        stack = result["stacks"][0]
        assert stack["name"] == "Native metadata burst", stack
        assert stack["sourcePaths"] == [frame_one, frame_two, frame_three], stack
        assert [item["sequence"] for item in stack["items"]] == [1, 2, 3], stack
        assert stack["keeperCount"] == 1, stack
        assert stack["coverSourcePath"] == frame_two, stack
        assert stack["items"][1]["keeper"] is True, stack
        assert stack["items"][1]["selectionRole"] == "keeper", stack

        collapsed_page = api.list_photo_folder_items({"folderId": "media:burst", "sort": "filename", "previewBudget": 0, "collapseBursts": True})
        assert collapsed_page["total"] == 1, collapsed_page
        collapsed_item = collapsed_page["items"][0]
        assert collapsed_item["sourcePath"] == frame_two, collapsed_item
        assert collapsed_item["burstStack"]["count"] == 3, collapsed_item
        assert collapsed_item["burstStack"]["keeperCount"] == 1, collapsed_item
    print("ok photo burst stack detection from native metadata identifiers")


