        api.project.db.record_scan_file("run1", near_b, _sig(near_b, size=near_b.stat().st_size), "completed", phase="processed", content_hash="near-b-hash")
        api.project.db.record_scan_file("run1", distant, _sig(distant, size=distant.stat().st_size), "completed", phase="processed", content_hash="distant-hash")

