def test_photo_utility_profiles_cover_set_clear_and_validate_membership() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        favorite_one = str(base / "favorite-one.jpg")
        favorite_two = str(base / "favorite-two.jpg")
        not_favorite = str(base / "not-favorite.jpg")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (favorite_one, favorite_two, not_favorite):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")

        api.update_photo_asset_metadata({"sourcePath": favorite_one, "favorite": True, "dateOverride": "2026-06-20"})
        api.update_photo_asset_metadata({"sourcePath": favorite_two, "favorite": True, "dateOverride": "2026-06-19"})
        api.update_photo_asset_metadata({"sourcePath": not_favorite, "dateOverride": "2026-06-18"})

        folders = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        assert folders["favorites"]["count"] == 2, folders
        assert folders["favorites"]["coverSourcePath"] == favorite_one, folders["favorites"]
        favorite_two_asset_id = str(api.project.db.photo_asset_by_path(favorite_two)["assetId"])
        profile = api.save_photo_utility_profile({"utilityId": "favorites", "keyAssetId": favorite_two_asset_id})
        assert profile["utilityId"] == "favorites", profile
        assert profile["keyAssetId"] == favorite_two_asset_id, profile
        folders_after_cover = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        favorites_after_cover = folders_after_cover["favorites"]
        assert favorites_after_cover["coverSourcePath"] == favorite_two, favorites_after_cover
        assert favorites_after_cover["utilityProfile"]["keyAssetId"] == favorite_two_asset_id, favorites_after_cover

        not_favorite_asset_id = str(api.project.db.photo_asset_by_path(not_favorite)["assetId"])
        try:
            api.save_photo_utility_profile({"utilityId": "favorites", "keyAssetId": not_favorite_asset_id})
            raise AssertionError("utility cover should reject assets outside the selected utility folder")
        except ValueError as exc:
            assert "selected utility folder" in str(exc), exc
        try:
            api.save_photo_utility_profile({"utilityId": "hidden", "keyAssetId": favorite_two_asset_id})
            raise AssertionError("sensitive utility folders should not accept custom covers")
        except ValueError as exc:
            assert "does not support custom covers" in str(exc), exc

        cleared = api.save_photo_utility_profile({"utilityId": "favorites", "keyAssetId": ""})
        assert cleared["keyAssetId"] == "", cleared
        folders_after_clear = {folder["id"]: folder for folder in api.list_photo_folders({})["folders"]}
        favorites_after_clear = folders_after_clear["favorites"]
        assert favorites_after_clear["coverSourcePath"] == favorite_one, favorites_after_clear
        assert favorites_after_clear["utilityProfile"]["keyAssetId"] == "", favorites_after_clear
    print("ok photo utility profile covers set clear and validate membership")


def test_photo_places_folders_group_visible_locations_and_hide_private_locations() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        beach_one = str(base / "beach-one.jpg")
