def test_photo_memories_generate_event_and_holiday_collections() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        christmas_tree = str(base / "christmas-tree.jpg")
        christmas_family = str(base / "family-christmas.jpg")
        hidden_christmas = str(base / "hidden-christmas.jpg")
        birthday_cake = str(base / "birthday-cake.jpg")
        birthday_party = str(base / "birthday-party.jpg")
        easter_brunch = str(base / "easter-brunch.jpg")
