def test_photo_people_group_best_mode_curates_group_pages_and_buckets() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        paths = [str(base / f"duo-{index:02d}.jpg") for index in range(16)]
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in paths:
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        candidates: dict[str, ReviewCandidate] = {}
        for index, path in enumerate(paths):
            quality = 0.20 if index == 0 else 0.40 + (index * 0.03)
            candidates[f"a-{index}"] = _candidate(
                f"a-{index}",
                "Alice",
                path,
                status="accepted",
                quality=quality,
                score=0.70 + (index * 0.01),
                capture_date=f"2026-01-{(index % 28) + 1:02d}T09:00:00Z",
            )
            candidates[f"b-{index}"] = _candidate(
                f"b-{index}",
                "Bob",
                path,
                status="accepted",
                quality=max(0.1, quality - 0.02),
                score=0.68 + (index * 0.01),
                capture_date=f"2026-01-{(index % 28) + 1:02d}T09:00:00Z",
            )
        api.project.candidates = candidates
        favorite_asset = api.project.db.photo_asset_by_path(paths[0])
        assert favorite_asset, favorite_asset
        api.update_photo_asset_metadata({"sourcePath": paths[0], "favorite": True})
        group = api.save_photo_people_group({"name": "Best Duo", "memberPeople": ["Alice", "Bob"]})
        folder_id = f"group:saved:{group['groupId']}"

        all_page = api.list_photo_folder_items({"folderId": folder_id, "groupMode": "all", "sort": "filename", "previewBudget": 0})
        assert all_page["total"] == 16, all_page
        best_page = api.list_photo_folder_items({"folderId": folder_id, "groupMode": "best", "sort": "filename", "previewBudget": 0})
        best_paths = [item["sourcePath"] for item in best_page["items"]]
        assert best_page["groupMode"] == "best", best_page
        assert best_page["total"] == 12, best_page
        assert paths[0] in best_paths, best_paths
        assert paths[15] in best_paths, best_paths
        assert paths[1] not in best_paths, best_paths

        best_buckets = api.list_photo_date_buckets({"folderId": folder_id, "mode": "years", "groupMode": "best"})
        assert [(bucket["key"], bucket["count"]) for bucket in best_buckets["buckets"]] == [("2026", 12)], best_buckets
    print("ok photo people group Best mode curates pages + buckets")


