def test_smart_album_people_group_sql_exact_and_saved_exclusions() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice_bob = str(base / "alice-bob.jpg")
        alice_bob_carol = str(base / "alice-bob-carol.jpg")
        alice_only = str(base / "alice-only.jpg")
        for path in (alice_bob, alice_bob_carol, alice_only):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alice_bob, alice_bob_carol, alice_only):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.db.backfill_photo_assets_from_scan_media()
        with api.project.db.connect() as conn:
            rows = conn.execute(
                "SELECT asset_id, source_path FROM photo_assets WHERE source_path IN (?, ?, ?)",
                (alice_bob, alice_bob_carol, alice_only),
            ).fetchall()
            asset_ids = {str(row["source_path"]): str(row["asset_id"]) for row in rows}
            now = datetime.now().isoformat()
            conn.executemany(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                """,
                [
                    (asset_ids[alice_bob], "group-sql-ab-a", "Alice", "accepted", 0.98, 0.94, "manual assignment", now),
                    (asset_ids[alice_bob], "group-sql-ab-b", "Bob", "accepted", 0.97, 0.93, "manual assignment", now),
                    (asset_ids[alice_bob_carol], "group-sql-abc-a", "Alice", "accepted", 0.96, 0.92, "manual assignment", now),
                    (asset_ids[alice_bob_carol], "group-sql-abc-b", "Bob", "accepted", 0.95, 0.91, "manual assignment", now),
                    (asset_ids[alice_bob_carol], "group-sql-abc-c", "Carol", "accepted", 0.94, 0.90, "manual assignment", now),
                    (asset_ids[alice_only], "group-sql-a", "Alice", "accepted", 0.93, 0.89, "manual assignment", now),
                ],
            )
        saved = api.save_photo_people_group({
            "name": "Core Duo",
            "memberPeople": ["Alice", "Bob"],
            "excludePeople": ["Carol"],
        })
        assert saved["excludePeople"] == ["Carol"], saved

        generated_group = api.save_photo_album({
            "name": "Generated Alice Bob SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "contains", "value": "Alice & Bob"}]},
        })
        assert generated_group["count"] == 2, generated_group
        fuzzy_group = api.save_photo_album({
            "name": "Fuzzy Alice group SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "contains", "value": "Alice"}]},
        })
        assert fuzzy_group["count"] == 2, fuzzy_group
        saved_group = api.save_photo_album({
            "name": "Saved Core Duo SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "contains", "value": "Core Duo"}]},
        })
        assert saved_group["count"] == 1, saved_group
        negative_generated = api.save_photo_album({
            "name": "Not Alice Bob SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "notContains", "value": "Alice & Bob"}]},
        })
        assert negative_generated["count"] == 1, negative_generated
        negative_fuzzy = api.save_photo_album({
            "name": "Not fuzzy Alice group SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "notContains", "value": "Alice"}]},
        })
        assert negative_fuzzy["count"] == 1, negative_fuzzy
        negative_saved = api.save_photo_album({
            "name": "Not Core Duo SQL",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "group", "operator": "notContains", "value": "Core Duo"}]},
        })
        assert negative_saved["count"] == 2, negative_saved

        original_all_entries = api._all_photo_entries
        original_asset_entries = api._photo_asset_entries

        def fail_python_assembly(*_args: Any, **_kwargs: Any) -> list[dict[str, Any]]:
            raise AssertionError("Exact people-group smart album pages should use SQL, not full Photos assembly.")

        api._all_photo_entries = fail_python_assembly
        api._photo_asset_entries = fail_python_assembly
        try:
            generated_page = api.list_photo_folder_items({"folderId": f"album:{generated_group['albumId']}", "previewBudget": 0})
            assert generated_page["total"] == 2, generated_page
            assert {item["sourcePath"] for item in generated_page["items"]} == {alice_bob, alice_bob_carol}, generated_page
            fuzzy_page = api.list_photo_folder_items({"folderId": f"album:{fuzzy_group['albumId']}", "previewBudget": 0})
            assert fuzzy_page["total"] == 2, fuzzy_page
            assert {item["sourcePath"] for item in fuzzy_page["items"]} == {alice_bob, alice_bob_carol}, fuzzy_page
            saved_page = api.list_photo_folder_items({"folderId": f"album:{saved_group['albumId']}", "previewBudget": 0})
            assert saved_page["total"] == 1, saved_page
            assert [item["sourcePath"] for item in saved_page["items"]] == [alice_bob], saved_page
            negative_generated_page = api.list_photo_folder_items({"folderId": f"album:{negative_generated['albumId']}", "previewBudget": 0})
            assert negative_generated_page["total"] == 1, negative_generated_page
            assert [item["sourcePath"] for item in negative_generated_page["items"]] == [alice_only], negative_generated_page
            negative_fuzzy_page = api.list_photo_folder_items({"folderId": f"album:{negative_fuzzy['albumId']}", "previewBudget": 0})
            assert negative_fuzzy_page["total"] == 1, negative_fuzzy_page
            assert [item["sourcePath"] for item in negative_fuzzy_page["items"]] == [alice_only], negative_fuzzy_page
            negative_saved_page = api.list_photo_folder_items({"folderId": f"album:{negative_saved['albumId']}", "previewBudget": 0})
            assert negative_saved_page["total"] == 2, negative_saved_page
            assert {item["sourcePath"] for item in negative_saved_page["items"]} == {alice_bob_carol, alice_only}, negative_saved_page
        finally:
            api._all_photo_entries = original_all_entries
            api._photo_asset_entries = original_asset_entries
    print("ok exact people-group smart album SQL")


def test_smart_album_group_fallback_reuses_saved_group_rows() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice_bob = str(base / "fallback-alice-bob.jpg")
        alice_bob_carol = str(base / "fallback-alice-bob-carol.jpg")
        alice_only = str(base / "fallback-alice-only.jpg")
        for path in (alice_bob, alice_bob_carol, alice_only):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alice_bob, alice_bob_carol, alice_only):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.candidates = {
            "fallback-ab-a": _candidate("fallback-ab-a", "Alice", alice_bob, status="accepted", score=0.99),
            "fallback-ab-b": _candidate("fallback-ab-b", "Bob", alice_bob, status="accepted", score=0.98),
            "fallback-abc-a": _candidate("fallback-abc-a", "Alice", alice_bob_carol, status="accepted", score=0.97),
            "fallback-abc-b": _candidate("fallback-abc-b", "Bob", alice_bob_carol, status="accepted", score=0.96),
            "fallback-abc-c": _candidate("fallback-abc-c", "Carol", alice_bob_carol, status="accepted", score=0.95),
            "fallback-a": _candidate("fallback-a", "Alice", alice_only, status="accepted", score=0.94),
        }
        api.project.db.upsert_candidates(api.project.candidates.values())
        api.save_photo_people_group({
            "name": "Fallback Core Duo",
            "memberPeople": ["Alice", "Bob"],
            "excludePeople": ["Carol"],
        })

        original_groups = api.project.db.list_photo_people_groups
        group_reads = 0

        def counting_groups(conn=None):  # type: ignore[no-untyped-def]
            nonlocal group_reads
            group_reads += 1
            return original_groups(conn)

        api.project.db.list_photo_people_groups = counting_groups  # type: ignore[method-assign]
        try:
            album = api.save_photo_album({
                "name": "Fallback saved group",
                "albumKind": "smart",
                "rules": {"op": "all", "conditions": [{"field": "group", "operator": "contains", "value": "Fallback Core Duo"}]},
            })
        finally:
            api.project.db.list_photo_people_groups = original_groups  # type: ignore[method-assign]

        assert album["count"] == 1, album
        assert group_reads <= 2, group_reads
    print("ok smart album group fallback reuses saved group rows")


