            pet_pair_page = api.list_photo_folder_items({"folderId": f"album:{generated_pet_pair['albumId']}", "sort": "filename", "previewBudget": 0})
            assert pet_pair_page["total"] == 2, pet_pair_page
            assert [item["sourcePath"] for item in pet_pair_page["items"]] == [alice_milo_luna, milo_luna], pet_pair_page
            pet_pair_label_page = api.list_photo_folder_items({"folderId": f"album:{generated_pet_pair_by_label['albumId']}", "sort": "filename", "previewBudget": 0})
            assert pet_pair_label_page["total"] == 2, pet_pair_label_page
            assert [item["sourcePath"] for item in pet_pair_label_page["items"]] == [alice_milo_luna, milo_luna], pet_pair_label_page
            saved_page = api.list_photo_folder_items({"folderId": f"album:{saved_group['albumId']}", "sort": "filename", "previewBudget": 0})
            assert saved_page["total"] == 1, saved_page
            assert [item["sourcePath"] for item in saved_page["items"]] == [alice_milo], saved_page
            saved_name_page = api.list_photo_folder_items({"folderId": f"album:{saved_group_by_name['albumId']}", "sort": "filename", "previewBudget": 0})
