            negative_page = api.list_photo_folder_items({"folderId": f"album:{negative_generated['albumId']}", "sort": "filename", "previewBudget": 0})
            assert negative_page["total"] == 1, negative_page
            assert [item["sourcePath"] for item in negative_page["items"]] == [milo_luna], negative_page
            fuzzy_page = api.list_photo_folder_items({"folderId": f"album:{fuzzy_mixed['albumId']}", "sort": "filename", "previewBudget": 0})
            assert fuzzy_page["total"] == 2, fuzzy_page
            assert {item["sourcePath"] for item in fuzzy_page["items"]} == {alice_milo, alice_milo_luna}, fuzzy_page
            negative_fuzzy_page = api.list_photo_folder_items({"folderId": f"album:{negative_fuzzy_mixed['albumId']}", "sort": "filename", "previewBudget": 0})
