def test_smart_album_query_dsl_all_any_groups() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice_family = str(base / "alice-family.jpg")
        alice_work = str(base / "alice-work.jpg")
        bob_family = str(base / "bob-family.jpg")
        alice_video = str(base / "alice-video.mov")
        for path in (alice_family, alice_work, bob_family, alice_video):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alice_family, alice_work, bob_family, alice_video):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.candidates = {
            "alice_family": _candidate("alice_family", "Alice", alice_family, status="accepted", score=0.97),
            "alice_work": _candidate("alice_work", "Alice", alice_work, status="accepted", score=0.96),
            "bob_family": _candidate("bob_family", "Bob", bob_family, status="accepted", score=0.95),
            "alice_video": _candidate("alice_video", "Alice", alice_video, status="accepted", score=0.93, media_kind="video"),
        }
        api.update_photo_asset_metadata({"sourcePath": alice_family, "keywords": ["family"], "favorite": True})
        api.update_photo_asset_metadata({"sourcePath": alice_work, "keywords": ["work"], "favorite": True})
        api.update_photo_asset_metadata({"sourcePath": bob_family, "keywords": ["family"], "favorite": True})
        api.update_photo_asset_metadata({"sourcePath": alice_video, "keywords": ["clips"], "favorite": True})
        api.project.db.update_photo_asset_metadata_json(
            source_path=alice_family,
            patch={
                "exif": {
                    "lensMake": "Nikon",
                    "lensModel": "Nikkor Z 50mm f/1.8 S",
                },
                "liveText": "Ticket number A123",
                "textRegions": [{"text": "Ticket number A123", "confidence": 0.88}],
                "objectTags": [{"label": "surfboard", "confidence": 0.94}],
                "accessibilityDescription": "Screen reader family beach description",
            },
        )
        api.project.db.update_photo_asset_metadata_json(
            source_path=bob_family,
            patch={
                "sceneTags": ["forest"],
                "detectedEvents": {"picnic": 0.72},
            },
        )
        with api.project.db.connect() as conn:
            conn.execute("UPDATE photo_assets SET width = 4000, height = 3000 WHERE source_path = ?", (alice_family,))
            conn.execute("UPDATE photo_assets SET width = 1600, height = 1200 WHERE source_path = ?", (alice_work,))
            conn.execute("UPDATE photo_assets SET width = 2048, height = 1536 WHERE source_path = ?", (bob_family,))
            conn.execute("UPDATE photo_assets SET width = 1920, height = 1080, duration_ms = 9000 WHERE source_path = ?", (alice_video,))

        album = api.save_photo_album({
            "name": "Alice family or video favorites",
            "albumKind": "smart",
            "rules": {
                "op": "all",
                "conditions": [
                    {"field": "favorite", "operator": "is", "value": True},
                    {"field": "person", "operator": "is", "value": "Alice"},
                    {
                        "op": "any",
                        "conditions": [
                            {"field": "keyword", "operator": "is", "value": "family"},
                            {"field": "mediaKind", "operator": "is", "value": "video"},
                        ],
                    },
                ],
            },
        })
        assert album["rules"]["op"] == "all", album["rules"]
        assert album["count"] == 2, album
        assert any(item.startswith("all(") for item in album["ruleSummary"]), album["ruleSummary"]

        page = api.list_photo_folder_items({"folderId": f"album:{album['albumId']}", "sort": "filename", "previewBudget": 0})
        paths = [item["sourcePath"] for item in page["items"]]
        assert paths == [alice_family, alice_video], paths

        nested = api.save_photo_album({
            "name": "DSL wrapper survives storage",
            "albumKind": "smart",
            "rules": {
                "queryDsl": {
                    "op": "any",
                    "conditions": [
                        {"field": "keyword", "operator": "is", "value": "work"},
                        {"field": "person", "operator": "isNot", "value": "Alice"},
                    ],
                },
            },
        })
        assert nested["rules"]["queryDsl"]["op"] == "any", nested["rules"]
        nested_page = api.list_photo_folder_items({"folderId": f"album:{nested['albumId']}", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in nested_page["items"]] == [alice_work, bob_family], nested_page["items"]

        detected = api.save_photo_album({
            "name": "Detected beach ticket",
            "albumKind": "smart",
            "rules": {
                "op": "all",
                "conditions": [
                    {"field": "ocrText", "operator": "contains", "value": "ticket number"},
                    {"field": "detectedItem", "operator": "contains", "value": "surfboard"},
                    {"field": "imageDescription", "operator": "contains", "value": "beach description"},
                ],
            },
        })
        assert detected["count"] == 1, detected
        detected_page = api.list_photo_folder_items({"folderId": f"album:{detected['albumId']}", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in detected_page["items"]] == [alice_family], detected_page["items"]

        detected_event = api.save_photo_album({
            "name": "Detected picnic",
            "albumKind": "smart",
            "rules": {"op": "all", "conditions": [{"field": "detectedEvent", "operator": "contains", "value": "picnic"}]},
        })
        assert detected_event["count"] == 1, detected_event
        detected_event_page = api.list_photo_folder_items({"folderId": f"album:{detected_event['albumId']}", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in detected_event_page["items"]] == [bob_family], detected_event_page["items"]

        bob_asset = api.project.db.photo_asset_by_path(bob_family)
        assert bob_asset is not None, bob_asset
