def test_smart_album_iptc_metadata_criteria() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        harbor = str(base / "harbor.jpg")
        archive = str(base / "archive.jpg")
        plain = str(base / "plain.jpg")
        for path in (harbor, archive, plain):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (harbor, archive, plain):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.db.update_photo_asset_metadata_json(
            source_path=harbor,
            patch={
                "xmp": {
                    "iptc": {
                        "creator": ["Harbor Studio", "A. Editor"],
                        "credit": "Unit News",
                        "source": "Harbor Archive",
                        "copyright": "Copyright 2026 Harbor Studio",
                        "usageTerms": "Editorial use only",
                        "event": "Bay Lights Opening",
                        "headline": "Ferry headline",
                        "jobId": "JOB-42",
                        "instructions": "Ask before syndication",
                        "locationCreated": {
                            "sublocation": "Ferry Building",
                            "city": "San Francisco",
                            "state": "California",
                            "country": "United States",
                            "countryCode": "US",
                        },
                    },
                },
            },
        )
        api.project.db.update_photo_asset_metadata_json(
            source_path=archive,
            patch={
                "iptc": {
                    "creator": "City Archivist",
                    "credit": "Museum Desk",
                    "source": "Historical Archive",
                    "rights": "Public domain review",
                    "usageTerms": "Research desk only",
                    "event": "Archive Intake",
                    "locationCreated": {
                        "sublocation": "Reading Room",
                        "city": "Oakland",
                        "country": "United States",
                    },
                },
            },
        )

        def save_paths(name: str, condition: dict[str, object]) -> tuple[dict[str, object], list[str]]:
            album = api.save_photo_album({
                "name": name,
                "albumKind": "smart",
                "rules": {"op": "all", "conditions": [condition]},
            })
            assert api._photo_smart_album_sql_criteria_branches(album) is not None, album
            assert "non-sql-smart-album-scale" not in {item["code"] for item in album.get("validation", [])}, album
            page = api.list_photo_folder_items({"folderId": f"album:{album['albumId']}", "sort": "filename", "previewBudget": 0})
            return album, [item["sourcePath"] for item in page["items"]]

        creator, creator_paths = save_paths(
            "IPTC creator aliases",
            {"field": "iptcCredit", "operator": "contains", "value": "Unit News"},
        )
        assert creator["count"] == 1, creator
        assert creator["rules"]["conditions"][0]["field"] == "iptcCreator", creator["rules"]
        assert creator_paths == [harbor], creator_paths

        rights, rights_paths = save_paths(
            "IPTC rights aliases",
            {"field": "iptcUsageTerms", "operator": "contains", "value": "Research"},
        )
        assert rights["count"] == 1, rights
        assert rights["rules"]["conditions"][0]["field"] == "iptcRights", rights["rules"]
        assert rights_paths == [archive], rights_paths

        event, event_paths = save_paths(
            "IPTC event exact",
            {"field": "iptcEvent", "operator": "is", "value": "Bay Lights Opening"},
        )
        assert event["count"] == 1, event
        assert event_paths == [harbor], event_paths

        location, location_paths = save_paths(
            "IPTC location",
            {"field": "iptcCity", "operator": "contains", "value": "Oakland"},
        )
        assert location["count"] == 1, location
        assert location["rules"]["conditions"][0]["field"] == "iptcLocation", location["rules"]
        assert location_paths == [archive], location_paths

        negative, negative_paths = save_paths(
            "IPTC creator negative",
            {"field": "iptcCreator", "operator": "isNot", "value": "Harbor Studio"},
        )
        assert negative["count"] == 2, negative
        assert negative_paths == [archive, plain], negative_paths
    print("ok smart album IPTC metadata criteria")


def test_smart_album_people_migration_dsl_matches_legacy_people_rules() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice = str(base / "alice.jpg")
        bob = str(base / "bob.jpg")
        alice_bob = str(base / "alice-bob.jpg")
        alice_carol = str(base / "alice-carol.jpg")
        indexed_alice = str(base / "indexed-alice.jpg")
        for path in (alice, bob, alice_bob, alice_carol, indexed_alice):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alice, bob, alice_bob, alice_carol, indexed_alice):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.candidates = {
            "alice": _candidate("alice", "Alice", alice, status="accepted", score=0.97),
            "bob": _candidate("bob", "Bob", bob, status="accepted", score=0.96),
            "ab-a": _candidate("ab-a", "Alice", alice_bob, status="accepted", score=0.95),
            "ab-b": _candidate("ab-b", "Bob", alice_bob, status="accepted", score=0.94),
            "ac-a": _candidate("ac-a", "Alice", alice_carol, status="accepted", score=0.93),
            "ac-c": _candidate("ac-c", "Carol", alice_carol, status="accepted", score=0.92),
        }
        indexed_asset = api.project.db.photo_asset_by_path(indexed_alice)
        assert indexed_asset, indexed_asset
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (indexed_asset["assetId"], "indexed-alice", "Alice", "accepted", 0.91, 0.88, "accepted", "2026-06-21T00:00:00Z"),
            )

        legacy = api.save_photo_album({
            "name": "Legacy people rules",
            "albumKind": "smart",
            "includePeople": ["Alice", "Bob"],
            "excludePeople": ["Carol"],
        })
        migrated = api.save_photo_album({
            "name": "Migrated people DSL",
            "albumKind": "smart",
            "rules": {
                "op": "all",
                "conditions": [
                    {
                        "op": "any",
                        "conditions": [
                            {"field": "person", "operator": "is", "value": "Alice"},
                            {"field": "person", "operator": "is", "value": "Bob"},
                        ],
                    },
                    {"field": "person", "operator": "isNot", "value": "Carol"},
                ],
            },
        })
        assert legacy["count"] == migrated["count"] == 4, (legacy, migrated)
        legacy_page = api.list_photo_folder_items({"folderId": f"album:{legacy['albumId']}", "sort": "filename", "previewBudget": 0})
        migrated_page = api.list_photo_folder_items({"folderId": f"album:{migrated['albumId']}", "sort": "filename", "previewBudget": 0})
        legacy_paths = [item["sourcePath"] for item in legacy_page["items"]]
        migrated_paths = [item["sourcePath"] for item in migrated_page["items"]]
        assert legacy_paths == migrated_paths == [alice_bob, alice, bob, indexed_alice], (legacy_paths, migrated_paths)
    print("ok smart album people migration DSL matches legacy people rules")


def test_migrate_photo_smart_albums_persists_dsl_without_changing_matches() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alice = str(base / "alice.jpg")
        bob = str(base / "bob.jpg")
        alice_bob = str(base / "alice-bob.jpg")
        alice_carol = str(base / "alice-carol.jpg")
        indexed_alice = str(base / "indexed-alice.jpg")
        for path in (alice, bob, alice_bob, alice_carol, indexed_alice):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alice, bob, alice_bob, alice_carol, indexed_alice):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.project.candidates = {
            "alice": _candidate("alice", "Alice", alice, status="accepted", score=0.97),
            "bob": _candidate("bob", "Bob", bob, status="accepted", score=0.96),
            "ab-a": _candidate("ab-a", "Alice", alice_bob, status="accepted", score=0.95),
            "ab-b": _candidate("ab-b", "Bob", alice_bob, status="accepted", score=0.94),
            "ac-a": _candidate("ac-a", "Alice", alice_carol, status="accepted", score=0.93),
            "ac-c": _candidate("ac-c", "Carol", alice_carol, status="accepted", score=0.92),
        }
        for path in (alice, bob, alice_bob, alice_carol, indexed_alice):
            asset = api.project.db.photo_asset_by_path(path)
            assert asset, path
            api.update_photo_asset_metadata(
                {
                    "assetId": asset["assetId"],
                    "favorite": True,
                    "keywords": ["family"],
                }
            )
        indexed_asset = api.project.db.photo_asset_by_path(indexed_alice)
        assert indexed_asset, indexed_asset
        with api.project.db.connect() as conn:
            conn.execute(
                """
                INSERT INTO photo_asset_people(asset_id, candidate_id, person_name, status, score, quality, band, updated_at)
                VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (indexed_asset["assetId"], "indexed-alice", "Alice", "accepted", 0.91, 0.88, "accepted", "2026-06-21T00:00:00Z"),
            )

        folder = api.save_photo_album_folder({"name": "People picks"})
        legacy = api.save_photo_album({
            "name": "Legacy persisted people rules",
            "albumKind": "smart",
            "description": "Keep this description",
            "includePeople": ["Alice", "Bob"],
            "excludePeople": ["Carol"],
            "rules": {"keyword": "family", "favoriteOnly": True},
            "coverSourcePath": alice_bob,
            "folderId": folder["folderId"],
        })
        before_page = api.list_photo_folder_items({"folderId": f"album:{legacy['albumId']}", "sort": "filename", "previewBudget": 0})
        before_paths = [item["sourcePath"] for item in before_page["items"]]
        assert before_paths == [alice_bob, alice, bob, indexed_alice], before_paths

        dry_run = api.migrate_photo_smart_albums({"albumId": legacy["albumId"]})
        assert dry_run["dryRun"] is True, dry_run
        assert dry_run["eligible"] == 1 and dry_run["migrated"] == 0, dry_run
        assert dry_run["albums"][0]["beforeCount"] == dry_run["albums"][0]["afterCount"] == 4, dry_run
        unchanged = api.project.db.photo_album_by_id(legacy["albumId"])
        assert unchanged and unchanged["includePeople"] == ["Alice", "Bob"], unchanged
        assert unchanged["excludePeople"] == ["Carol"], unchanged

        applied = api.migrate_photo_smart_albums({"albumId": legacy["albumId"], "apply": True})
        assert applied["dryRun"] is False and applied["migrated"] == 1, applied
        assert applied["albums"][0]["beforeCount"] == applied["albums"][0]["afterCount"] == 4, applied
        stored = api.project.db.photo_album_by_id(legacy["albumId"])
        assert stored, stored
        assert stored["includePeople"] == [] and stored["excludePeople"] == [], stored
        assert stored["description"] == "Keep this description", stored
        assert stored["coverSourcePath"] == alice_bob, stored
        assert stored["folderId"] == folder["folderId"], stored
        assert stored["rules"]["op"] == "all", stored["rules"]

        def collect_fields(node: dict) -> set[str]:
            if "conditions" in node:
                fields: set[str] = set()
                for child in node.get("conditions", []) or []:
                    if isinstance(child, dict):
                        fields.update(collect_fields(child))
                return fields
            return {str(node.get("field", "") or "")}

        fields = collect_fields(stored["rules"])
        assert {"person", "keyword", "favorite"}.issubset(fields), stored["rules"]
        after_page = api.list_photo_folder_items({"folderId": f"album:{legacy['albumId']}", "sort": "filename", "previewBudget": 0})
        after_paths = [item["sourcePath"] for item in after_page["items"]]
        assert after_paths == before_paths, (before_paths, after_paths)
    print("ok smart album migration persists DSL without changing matches")


def test_merge_manual_photo_albums_dedupes_items_and_preserves_metadata() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        alpha = str(base / "alpha.jpg")
        beta = str(base / "beta.jpg")
        gamma = str(base / "gamma.jpg")
        for path in (alpha, beta, gamma):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (alpha, beta, gamma):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")

        target = api.save_photo_album({"name": "Target manual", "albumKind": "manual", "description": "Target description"})
        source = api.save_photo_album({"name": "Source manual", "albumKind": "manual", "description": "Source description", "coverSourcePath": gamma})
        api.add_photo_album_items({"albumId": target["albumId"], "sourcePaths": [alpha, beta]})
        api.add_photo_album_items({"albumId": source["albumId"], "sourcePaths": [beta, gamma]})

        merged = api.merge_photo_albums({"targetAlbumId": target["albumId"], "sourceAlbumIds": [source["albumId"]]})
        assert merged["added"] == 1, merged
        assert merged["duplicates"] == 1, merged
        assert merged["deletedSourceAlbumIds"] == [source["albumId"]], merged
        assert merged["folder"]["coverSourcePath"] == gamma, merged["folder"]
        assert "Target description" in merged["folder"]["description"], merged["folder"]["description"]
        assert "Merged from Source manual: Source description" in merged["folder"]["description"], merged["folder"]["description"]
        page = api.list_photo_folder_items({"folderId": f"album:{target['albumId']}", "sort": "manual", "previewBudget": 0})
        assert [item["sourcePath"] for item in page["items"]] == [alpha, beta, gamma], page["items"]
        assert api.project.db.photo_album_by_id(source["albumId"]) is None
    print("ok merge manual photo albums dedupes items + preserves metadata")


def test_merge_smart_photo_albums_unions_rules_and_rejects_manual_sources() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        api = _api(tmp)
        base = Path(tmp)
        family = str(base / "family.jpg")
        favorite = str(base / "favorite.jpg")
        other = str(base / "other.jpg")
        for path in (family, favorite, other):
            Path(path).write_bytes(b"photo")
        api.project.db.create_scan_run("run1", "label", "manual", str(base))
        for path in (family, favorite, other):
            api.project.db.record_scan_file("run1", Path(path), _sig(Path(path)), "completed", phase="processed")
        api.update_photo_asset_metadata({"sourcePath": family, "keywords": ["family"]})
        api.update_photo_asset_metadata({"sourcePath": favorite, "favorite": True})

        target = api.save_photo_album({"name": "Family smart", "albumKind": "smart", "rules": {"keyword": "family"}})
        source = api.save_photo_album({"name": "Favorite smart", "albumKind": "smart", "rules": {"favoriteOnly": True}, "coverSourcePath": favorite})
        merged = api.merge_photo_albums({"targetAlbumId": target["albumId"], "sourceAlbumIds": [source["albumId"]]})
        assert merged["albumKind"] == "smart", merged
        assert merged["deletedSourceAlbumIds"] == [source["albumId"]], merged
        assert merged["folder"]["rules"]["op"] == "any", merged["folder"]["rules"]
        assert merged["folder"]["coverSourcePath"] == favorite, merged["folder"]
        page = api.list_photo_folder_items({"folderId": f"album:{target['albumId']}", "sort": "filename", "previewBudget": 0})
        assert [item["sourcePath"] for item in page["items"]] == [family, favorite], page["items"]
        assert api.project.db.photo_album_by_id(source["albumId"]) is None

        manual = api.save_photo_album({"name": "Manual source", "albumKind": "manual"})
        api.add_photo_album_items({"albumId": manual["albumId"], "sourcePaths": [other]})
        _expect_raises(
            ValueError,
            lambda: api.merge_photo_albums({"targetAlbumId": target["albumId"], "sourceAlbumIds": [manual["albumId"]]}),
            "manual target",
        )
    print("ok merge smart photo albums unions rules + rejects manual sources")


