        assert templated_manifest["filenameTemplate"] == "{sequence}-{title}-{person}-{kind}", templated_manifest
        assert templated_manifest["subfolderTemplate"] == "{date}/{album}/{sourceFolder}", templated_manifest
        templated_row = templated["items"][0]
