        assert custom_targeted_row["targetColorProfilePath"] == custom_profile_path, custom_targeted_row
        with Image.open(Path(custom_targeted_row["targetPath"])) as output:
            assert output.info.get("icc_profile") == icc_profile, output.info.keys()
        custom_targeted_manifest = json.loads(Path(custom_targeted["manifestPath"]).read_text(encoding="utf-8"))
        assert custom_targeted_manifest["targetColorProfile"] == "custom-icc", custom_targeted_manifest
        assert custom_targeted_manifest["targetColorProfilePath"] == custom_profile_path, custom_targeted_manifest

        invalid_profile = base / "not-a-profile.icc"
        invalid_profile.write_text("not an ICC profile", encoding="utf-8")
        try:
            api.validate_photo_color_profile({"path": str(invalid_profile)})
            raise AssertionError("Expected invalid ICC preflight to fail")
        except ValueError as exc:
            assert "valid ICC/ICM" in str(exc), exc

        try:
            api.export_photo_selection(
                [imported_plain],
                export_variant="rendered",
                render_format="png",
                target_color_profile="custom-icc",
                filename_mode="original",
            )
            raise AssertionError("Expected custom ICC export without a profile path to fail")
        except ValueError as exc:
            assert "targetColorProfilePath" in str(exc), exc

        profile_pack_root = base / "profile-pack"
        profile_pack_root.mkdir()
